n\n (auto-responds to dark/system mode via ReadMe's mixin) */\n.hub-is-home .undefined.container {\n background: var(--color-bg-page);\n width: 100%;\n}\n\n/* ============================================================\n FONTS\n Amazon Ember is the site-wide body + heading typeface.\n ReadMe now uses --font-family-body and --font-family-heading,\n so define those alongside the existing --font-family token.\n ============================================================ */\n\n@font-face {\n font-family: \"Ember\";\n src: url(\"https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Rg.ttf\") format(\"truetype\");\n font-weight: 400;\n font-style: normal;\n font-display: swap;\n}\n\n@font-face {\n font-family: \"Ember\";\n src: url(\"https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Bd.ttf\") format(\"truetype\");\n font-weight: 700;\n font-style: normal;\n font-display: swap;\n}\n\n@font-face {\n font-family: \"Ember\";\n src: url(\"https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_RgIt.ttf\") format(\"truetype\");\n font-weight: 400;\n font-style: italic;\n font-display: swap;\n}\n\n/* ============================================================\n BASE VARIABLES & TYPOGRAPHY\n ============================================================ */\n\n:root,\nbody,\n.rm-ReadMe {\n --amazon-font-family: \"Ember\", -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n Roboto, Oxygen, Ubuntu, Cantarell, \"Fira Sans\", \"Droid Sans\",\n \"Helvetica Neue\", sans-serif;\n\n /* Legacy/custom token still used by existing site CSS */\n --font-family: var(--amazon-font-family);\n\n /* Current ReadMe typography tokens */\n --font-family-body: var(--amazon-font-family);\n --font-family-heading: var(--amazon-font-family);\n\n --font-weight: 400;\n --font-weight-bold: 700;\n --border-radius: 8px;\n --spruce: #067D62; /* success green */\n --lake: #1196AB; /* info blue */\n --pacific: #007185; /* link blue (light mode) */\n --river: #3DB7CC; /* link blue (dark