t.getElementById(\"hub-subheader-parent\").remove();\n \n /****** ADA Accessibility Fixes (Consolidated for SPA) ******/\n \n (function ADAFixes() {\n /*** #1 - Unique labeling in nav/footer landmarks ***/\n function fixLandmarkLabels() {\n let navProcessed = 0;\n const navs = document.querySelectorAll('nav[role=\"navigation\"], nav');\n const navLabelsCount = {};\n navs.forEach((nav, idx) => {\n let label = nav.getAttribute(\"aria-label\") || \"\";\n if (!label.trim()) {\n label = `Navigation region ${idx + 1}`;\n nav.setAttribute(\"aria-label\", label);\n }\n if (navLabelsCount[label]) {\n const newLabel = `${label} (${navLabelsCount[label] + 1})`;\n nav.setAttribute(\"aria-label\", newLabel);\n navLabelsCount[label]++;\n } else {\n navLabelsCount[label] = 1;\n }\n navProcessed++;\n });\n let footerProcessed = 0;\n const footers = document.querySelectorAll(\n 'footer[role=\"contentinfo\"], footer'\n );\n const footerLabelsCount = {};\n footers.forEach((footer, idx) => {\n let label = footer.getAttribute(\"aria-label\") || \"\";\n if (!label.trim()) {\n label = `Footer region ${idx + 1}`;\n footer.setAttribute(\"aria-label\", label);\n }\n if (footerLabelsCount[label]) {\n const newLabel = `${label} (${footerLabelsCount[label] + 1})`;\n footer.setAttribute(\"aria-label\", newLabel);\n footerLabelsCount[label]++;\n } else {\n footerLabelsCount[label] = 1;\n }\n footerProcessed++;\n });\n }\n \n /*** #5 - Headings need heading element or role ***/\n function fixHeadings() {\n let count = 0;\n document\n .querySelectorAll(\".heading-anchor_backwardsCompatibility\")\n .forEach((el) => {\n if (!el.closest(\"h1, h2, h3, h4, h5, h6\")) {\n el.setAttribute(\"role\", \"heading\");\n el.setAttribute(\"aria-level\", \"2\");\n count++;\n }\n });\n }\n \n /*** #7 - Code block tabs are not keyboard navigable ***/\n const enhancedCodeTabs = new WeakSet();\n function enhanceCodeTabs() {\n let processed = 0;\n document.querySelectorAll(\".CodeTabs\").forEach((codeTabs) => {\n if (enhancedCodeTabs.has(codeTabs)) return;\n enhancedCodeTabs.add(codeTabs);\n processed++;\n const tablist = codeTabs.querySelector(\n '.CodeTabs-toolbar[role=\"tablist\"]'\n );\n const panel = codeTabs.querySelector('.CodeTabs-inner[role=\"tabpanel\"]');\n if (!tablist || !panel) return;\n const tabs = tablist.querySelectorAll('button[role=\"tab\"]');\n tabs.forEach((tab) => {\n if (!tab.id) {\n tab.id = `tab-${Math.random().toString(36).substr(2, 8)}`;\n }\n tab.addEventListener(\"keydown\", (event) => {\n const i = Array.from(tabs).indexOf(event.target);\n if (event.key === \"ArrowRight\") {\n event.preventDefault();\n tabs[(i + 1) % tabs.length].focus();\n } else if (event.key === \"ArrowLeft\") {\n event.preventDefault();\n tabs[(i - 1 + tabs.length) % tabs.length].focus();\n }\n });\n tab.addEventListener(\"click\", (event) => {\n tabs.forEach((t) => {\n t.setAttribute(\"aria-selected\", \"false\");\n t.classList.remove(\"CodeTabs_active\");\n });\n const active = event.target;\n active.setAttribute(\"aria-selected\", \"true\");\n active.classList.add(\"CodeTabs_active\");\n panel.setAttribute(\"aria-labelledby\", active.id);\n });\n });\n const activeTab =\n tablist.querySelector('button[aria-selected=\"true\"]') || tabs[0];\n if (activeTab) {\n panel.setAttribute(\"aria-labelledby\", activeTab.id);\n }\n });\n }\n \n /*** #8 - Widget roles are not actually tabbable ***/\n function fixWidgetRoles() {\n let processed = 0;\n const roles = [\"button\", \"link\", \"checkbox\", \"switch\", \"tab\", \"menuitem\"];\n roles.forEach((role) => {\n document.querySelectorAll(`[role=\"${role}\"]`).forEach((el) => {\n const tag = el.tagName;\n if ([\"A\", \"BUTTON\", \"INPUT\", \"TEXTAREA\", \"SELECT\"].includes(tag))\n return;\n \n // Skip anything inside the search container\n if (el.closest(\"#hub-search\")) return;\n \n if (!el.hasAttribute(\"tabindex\")) el.setAttribute(\"tabindex\", \"0\");\n processed++;\n \n if (role === \"button\" && !el.dataset._hasKeyHandler) {\n el.addEventListener(\"keydown\", (e) => {\n // Only simulate click on ENTER; leave SPACE alone unless you're sure\n if (e.key === \"Enter\") {\n e.preventDefault();\n el.click?.();\n }\n });\n el.dataset._hasKeyHandler = \"true\";\n }\n });\n });\n }\n \n /*** #9 - \u003ctable> elements have no accessible name ***/\n function labelTables() {\n let processed = 0;\n document.querySelectorAll(\"table\").forEach((table, i) => {\n if (\n table.hasAttribute(\"aria-label\") ||\n table.hasAttribute(\"aria-labelledby\") ||\n table.hasAttribute(\"title\")\n )\n return;\n const caption = table.querySelector(\"caption\");\n if (caption?.textContent.trim()) {\n table.setAttribute(\"aria-label\", caption.textContent.trim());\n processed++;\n return;\n }\n let prev = table.previousElementSibling;\n while (prev && !/^H[1-6]$/.test(prev.tagName)) {\n prev = prev.previousElementSibling;\n }\n if (prev?.textContent.trim()) {\n table.setAttribute(\"aria-label\", prev.textContent.trim());\n processed++;\n return;\n }\n table.setAttribute(\"aria-label\", `Data table ${i + 1}`);\n processed++;\n });\n }\n \n /*** #10 - \u003cblockquote> used for layout, not quotes ***/\n function fixBlockquotes() {\n let processed = 0;\n document.querySelectorAll(\"blockquote.callout\").forEach((bq) => {\n if (bq.hasAttribute(\"cite\")) return;\n const newEl = document.createElement(\"div\");\n newEl.className = bq.className;\n if (bq.hasAttribute(\"theme\"))\n newEl.setAttribute(\"theme\", bq.getAttribute(\"theme\"));\n newEl.innerHTML = bq.innerHTML;\n bq.replaceWith(newEl);\n processed++;\n });\n }\n \n /*** #11 - Inline quotes not wrapped in semantic \u003cq> ***/\n function fixInlineQuotes() {\n let processed = 0;\n document.querySelectorAll(\"p\").forEach((p) => {\n const text = p.textContent.trim();\n if (/^[\"“].+[\"”]$/.test(text) && !p.querySelector(\"q\")) {\n const quote = text.replace(/^[\"“]|[\"”]$/g, \"\");\n p.innerHTML = `\u003cq>${quote}\u003c/q>`;\n processed++;\n }\n });\n }\n \n /*** #12 - Label names for icons (expand/collapse) ***/\n function fixIconLabels() {\n let processed = 0;\n // Find all icon elements that are used for expand/collapse, assumed to have a specific class\n document\n .querySelectorAll(\"i.Sidebar-link-expandIcon2yVH6SarI6NW\")\n .forEach((icon) => {\n if (!icon.hasAttribute(\"aria-label\")) {\n // Check the parent button's aria-expanded attribute to infer state\n const parentBtn = icon.closest(\"button\");\n let label = \"Expand\";\n if (parentBtn) {\n const expanded = parentBtn.getAttribute(\"aria-expanded\");\n label = expanded === \"true\" ? \"Collapse\" : \"Expand\";\n }\n icon.setAttribute(\"role\", \"img\");\n icon.setAttribute(\"aria-label\", label);\n processed++;\n }\n });\n }\n \n /*** #13 - Warn users before opening a new window ***/\n function fixExternalLinks() {\n let processed = 0;\n document.querySelectorAll('a[target=\"_blank\"]').forEach((link) => {\n let text = link.innerText.trim() || link.textContent.trim();\n if (text && !text.toLowerCase().includes(\"opens in a new window\")) {\n const newLabel = `${text} (opens in a new window)`;\n link.setAttribute(\"aria-label\", newLabel);\n processed++;\n }\n });\n }\n \n /*** Master apply function ***/\n function applyAllFixes() {\n fixLandmarkLabels(); // #1: Unique labeling in top nav bar, footer, side mini TOC\n fixHeadings(); // #5: Headings need heading element or role\n enhanceCodeTabs(); // #7: Code block tabs are not keyboard navigable\n fixWidgetRoles(); // #8: Widget roles are not actually tabbable\n labelTables(); // #9: \u003ctable> elements have no accessible name\n\n fixInlineQuotes(); // #11: Inline quotes not wrapped in semantic \u003cq>\n fixIconLabels(); // #12: Label names for icons (expand/collapse)\n fixExternalLinks(); // #13: Warn users before opening a new window\n }\n \n applyAllFixes();\n \n let debounceTimer;\n const observer = new MutationObserver((mutations) => {\n clearTimeout(debounceTimer);\n debounceTimer = setTimeout(() => {\n try {\n applyAllFixes();\n } catch (error) {\n }\n }, 300);\n });\n \n observer.observe(document.body, {\n childList: true,\n subtree: true,\n });\n })();","html_promo":"","html_body":"","html_footer":"\u003cstyle>\n .footer-container {\n display: flex;\n align-items: center;\n justify-content: space-between;\n gap: 24px;\n width: 100%;\n margin-top: 32px;\n padding: 24px 40px;\n box-sizing: border-box;\n border-top: 1px solid #dfe5e7;\n background: #f7f9f9;\n color: #5f6d73;\n font-size: 14px;\n line-height: 1.5;\n }\n\n .footer-left-container,\n .footer-sub-container {\n display: flex;\n align-items: center;\n }\n\n .footer-container a {\n color: #526f79;\n font-weight: 500;\n text-decoration: none;\n transition: color 0.15s ease;\n }\n\n .footer-container a:hover {\n color: #263f49;\n text-decoration: underline;\n }\n\n /* Dark Mode */\n [data-color-mode=\"dark\"] .footer-container {\n background: #131b28;\n border-top-color: #344052;\n color: #aeb8c4;\n }\n\n [data-color-mode=\"dark\"] .footer-container a {\n color: #b6d0d3;\n }\n\n [data-color-mode=\"dark\"] .footer-container a:hover {\n color: #ffffff;\n }\n\n /* Mobile */\n @media (max-width: 768px) {\n .footer-container {\n flex-direction: column;\n align-items: flex-start;\n gap: 12px;\n padding: 22px 20px;\n }\n\n .footer-sub-container {\n flex-wrap: wrap;\n }\n }\n\u003c/style>\n\n\u003cdiv class=\"footer-container\">\n \u003cspan class=\"footer-left-container\">\n \u003ca href=\"https://developer-docs.amazon.com/sp-api/docs/policies-and-agreements\">\n Policies and Agreements\n \u003c/a>\n &nbsp;&nbsp;\n \u003cspan id=\"policySection\">\u003c/span>\n \u003c/span>\n\n \u003cspan class=\"footer-sub-container\">\n \u003ca href=\"https://www.amazon.com/gp/help/customer/display.html/ref=ap_signin_notification_privacy_notice?ie=UTF8&nodeId=468496\">\n Privacy notice\n \u003c/a>\n &nbsp;&nbsp;|&nbsp;&nbsp;\n \u003ca href=\"https://www.amazon.com/gp/help/customer/display.html/ref=ap_signin_notification_condition_of_use?ie=UTF8&nodeId=508088\">\n Conditions of use\n \u003c/a>\n \u003cspan id=\"copyrightSection\">\u003c/span>\n \u003c/span>\n\u003c/div>","html_head":"\u003cscript>\n(function() {\n // Dark-mode logo URL\n const DARK_LOGO_URL = 'https://files.readme.io/3e67286554d385b8b9f2eb2d92c59aa852f151a95805ca6d6eaea9c7ba3f8612-small-sp-api-logo-dark.png';\n // Selector matching your logo \u003cimg>\n const logoSelector = '.rm-Logo-img';\n\n let originalLogoSrc;\n\n function updateLogo() {\n const logoImg = document.querySelector(logoSelector);\n if (!logoImg) {\n // If not found yet, retry shortly\n setTimeout(updateLogo, 500);\n return;\n }\n // Store original src once\n if (originalLogoSrc === undefined) {\n originalLogoSrc = logoImg.src;\n }\n const mode = document.documentElement.getAttribute('data-color-mode');\n if (mode === 'dark') {\n if (logoImg.src !== DARK_LOGO_URL) {\n logoImg.src = DARK_LOGO_URL;\n }\n } else {\n if (logoImg.src !== originalLogoSrc) {\n logoImg.src = originalLogoSrc;\n }\n }\n }\n\n // On DOM ready, wait a moment then run updateLogo\n if (document.readyState === 'loading') {\n document.addEventListener('DOMContentLoaded', () => {\n setTimeout(updateLogo, 1000);\n });\n } else {\n setTimeout(updateLogo, 1000);\n }\n\n // Observe changes to data-color-mode on \u003chtml>\n const observer = new MutationObserver(mutations => {\n for (const m of mutations) {\n if (m.type === 'attributes' && m.attributeName === 'data-color-mode') {\n updateLogo();\n }\n }\n });\n observer.observe(document.documentElement, { attributes: true });\n})();\n\u003c/script>","html_footer_meta":"\u003c!-- Keep the language selector commented -->\n\u003c!--\n\u003cselect id=\"global-lang\" class=\"language-selector\" onchange=\"redirectToSelectedLanguage(this)\">\n \u003coption value=\"amazon-group.readme.io\">English\u003c/option>\n \u003coption value=\"amazon-portuguese-group.readme.io\">Portuguese\u003c/option>\n \u003coption value=\"amazon-japanese-group.readme.io\">Jap