glp-footer a,\n [data-color-mode=\"auto\"] .glp-page .glp-footer a {\n color: #b6d0d3;\n }\n\n [data-color-mode=\"system\"] .glp-page .glp-footer a:hover,\n [data-color-mode=\"auto\"] .glp-page .glp-footer a:hover {\n color: #ffffff;\n }\n }\n\n\n /* =========================================================\n MOBILE\n ========================================================= */\n\n @media (max-width: 768px) {\n\n .glp-page #sub-header-container {\n padding: 56px 20px;\n }\n\n .glp-page #sub-header-container .LandingPageHeader {\n font-size: 36px !important;\n }\n\n .glp-page #bodyText {\n padding: 42px 20px 16px;\n }\n\n .glp-page .main-card {\n grid-template-columns: 1fr;\n\n padding: 10px 20px 40px;\n }\n\n .glp-page .card-sp {\n min-height: auto;\n }\n\n .glp-page .glp-footer {\n flex-direction: column;\n align-items: flex-start;\n\n gap: 12px;\n\n padding: 22px 20px;\n }\n\n .glp-page .glp-footer-right {\n flex-wrap: wrap;\n }\n }\n\u003c/style>\n\n\n\u003cdiv class=\"glp-page\">\n\n \u003c!-- =======================================================\n HERO\n ======================================================= -->\n\n \u003cdiv id=\"sub-header-container\">\n\n \u003csection class=\"sub-header-section\">\n\n \u003ch1 class=\"LandingPageHeader\">\n Amazon Selling Partner API\n \u003c/h1>\n\n \u003c/section>\n\n \u003c/div>\n\n\n \u003cdiv class=\"bottom_border\">\u003c/div>\n\n\n \u003c!-- =======================================================\n CONTENT\n ======================================================= -->\n\n \u003cdiv class=\"glp-content\">\n\n \u003cdiv id=\"bodyText\">\n\n \u003ch2 id=\"bodyTextHeader\">\n Developer Products\n \u003c/h2>\n\n \u003c/div>\n\n\n \u003cdiv class=\"main-card\">\n\n\n \u003c!-- ===================================================\n DOCUMENTATION CARD\n =================================================== -->\n\n \u003cdiv class=\"card-sp\">\n\n \u003cdiv class=\"cardContainer\">\n\n \u003ch3>\n Selling Partner API Documentation\n \u003c/h3>\n\n \u003c/div>\n\n\n \u003cdiv class=\"cardSubContainer\">\n\n \u003cdiv class=\"textContainer\">\n\n \u003cp class=\"card-description\">\n Learn how to get started and build applications with Amazon's REST-based SP-API.\n \u003c/p>\n\n\n \u003cp class=\"card-link-wrap\">\n\n \u003ca\n class=\"card-link\"\n href=\"https://developer-docs.amazon.com/sp-api\"\n >\n Learn more\n \u003c/a>\n\n \u003c/p>\n\n \u003c/div>\n\n \u003c/div>\n\n \u003c/div>\n\n\n \u003c!-- ===================================================\n CODE SAMPLES CARD\n =================================================== -->\n\n \u003cdiv class=\"card-sp\">\n\n \u003cdiv class=\"cardContainer\">\n\n \u003ch3>\n Selling Partner API Code Samples\n \u003c/h3>\n\n \u003c/div>\n\n\n \u003cdiv class=\"cardSubContainer\">\n\n \u003cdiv class=\"textContainer\">\n\n \u003cp class=\"card-description\">\n Walkthroughs that highlight the capabilities of APIs, best practices, and optimal use cases.\n \u003c/p>\n\n\n \u003cp class=\"card-link-wrap\">\n\n \u003ca\n class=\"card-link\"\n href=\"https://developer-docs.amazon.com/sp-api/recipes\"\n >\n Learn more\n \u003c/a>\n\n \u003c/p>\n\n \u003c/div>\n\n \u003c/div>\n\n \u003c/div>\n\n \u003c/div>\n\n \u003c/div>\n\n\n \u003c!-- =======================================================\n GLP-ONLY FOOTER\n ======================================================= -->\n\n \u003cdiv class=\"glp-footer\">\n\n\n \u003cspan class=\"glp-footer-left\">\n\n \u003ca href=\"https://developer-docs.amazon.com/sp-api/docs/policies-and-agreements\">\n Policies and Agreements\n \u003c/a>\n\n &nbsp;&nbsp;\n\n \u003cspan id=\"policySection\">\u003c/span>\n\n \u003c/span>\n\n\n \u003cspan class=\"glp-footer-right\">\n\n \u003ca href=\"https://www.amazon.com/gp/help/customer/display.html/ref=ap_signin_notification_privacy_notice?ie=UTF8&nodeId=468496\">\n Privacy notice\n \u003c/a>\n\n &nbsp;&nbsp;|&nbsp;&nbsp;\n\n \u003ca href=\"https://www.amazon.com/gp/help/customer/display.html/ref=ap_signin_notification_condition_of_use?ie=UTF8&nodeId=508088\">\n Conditions of use\n \u003c/a>\n\n \u003cspan id=\"copyrightSection\">\u003c/span>\n\n \u003c/span>\n\n\n \u003c/div>\n\n\u003c/div>","redirect":""},"html_hidelinks":false,"collapsibleCategories":false,"showBreadcrumbs":false,"showPageIcons":true,"showVersion":true,"searchModal":"classic","hideTableOfContents":false,"nextStepsLabel":"","ai_dropdown":"disabled","ai_options":{"ask_ai":"disabled","chatgpt":"enabled","claude":"enabled","clipboard":"enabled","copilot":"enabled","mcp":{"command":"enabled","config":"enabled","cursor":"enabled","vscode":"enabled"},"view_as_markdown":"enabled"}},"custom_domain":"developer-docs.amazon","description":"Amazon API Services for Selling Partners and Shippers.","hstsIncludeSubdomains":false,"planSchedule":{"stripeScheduleId":null,"changeDate":null,"nextPlan":null},"planStatus":"","error404":"","first_page":"landing","git":{"migration":{"createRepository":{"end":"2026-09-09T08:51:04.754Z","start":"2026-09-09T08:51:04.212Z","status":"successful"},"transformation":{"end":"2026-09-09T08:51:05.580Z","start":"2026-09-09T08:51:05.076Z","status":"successful"},"migratingPages":{"end":"2026-09-09T08:51:06.014Z","start":"2026-09-09T08:51:05.732Z","status":"successful"},"enableSuperhub":{"end":"2026-09-09T08:51:14.265Z","start":"2026-09-09T08:51:14.264Z","status":"successful"}},"migrationType":"preview","renamedSlugs":[]},"glossaryTerms":[{"_id":"67a686dbc28d4400588f3249","term":"Selling partner","definition":"A business that works with Amazon as a seller or a vendor. Selling partners manage their business through a workflow that includes planning inventory, creating listings, managing prices, receiving orders, and fulfilling sales."},{"_id":"67b8f33f408fe90055a5f153","term":"Solution Provider Portal","definition":"A dedicated gateway for third party developers and service providers to onboard and manage their offerings to Amazon seller and vendor customers."},{"_id":"67b8f45775f3300012d585aa","term":"Developer","definition":"A person or organization who builds applications using the SP-API on behalf of a selling partner."},{"_id":"67bb9aa988608f007a3aa269","term":"Sandbox","definition":"A test environment for that you can use to try SP-API operations and test your application. Includes a static sandbox that returns mocked responses for all operations, and a dynamic sandbox that provides realistic responses for select APIs (Fulfillment Outbound, FBA Inventory, and Vendor Direct Fulfillment)."},{"_id":"67c0e71af3a3400012a7f0a5","term":"Authorization","definition":"The process by which a selling partner grants an application permission to call SP-API on the selling partner's behalf. The authorization method is either OAuth 2.0 (public applications) or self-authorization (private applications)."},{"_id":"67c1016cfa256f003e81ff2f","term":"REST","definition":"An architectural style in which web services use HTTP methods to interact with resources. URLs identify the resources, and client-server communication is stateless."},{"_id":"67c106c839fbae0059aac409","term":"Role","definition":"The mechanism by which SP-API determines if a developer or application has access to an operation or resource. To access the operations and resources grouped under a role, you must request and qualify for that role."},{"_id":"67c10b5e77bc7d0062d0751f","term":"Refresh token","definition":"A long-lived credential that your application uses to get new access tokens without requiring the selling partner to re-authorize."},{"_id":"67c10d21c5cce30029556925","term":"Client ID","definition":"An identifier that Amazon issues when you register your app in the Solution Provider Portal. You use this ID to get access tokens when you call the Selling Partner API."},{"_id":"67c10d7602a53b004ce3f5db","term":"Client secret","definition":"A private key that proves your application's identity. Amazon issues your client secret when you register your app in the Solution Provider Portal."},{"_id":"67c10d9dcf01be000f2867cd","term":"Application ID","definition":"A unique identifier that the Solution Provider Portal assigns to your application. You use this ID in authorization URLs when sellers authorize your application."},{"_id":"67c113c033f0230010a352e2","term":"Login URI","definition":"A URI that lets selling partners log in to your website during the OAuth authorization flow."},{"_id":"67c113efa091ec0033d20358","term":"Authorization URI","definition":"A URI that lets selling partners authorize your application to access their data."},{"_id":"67c11409aa360a0075c10a8e","term":"Redirect URI","definition":"A URI that redirects selling partners back to your website after authorization is complete."},{"_id":"67f83afaf530980012375d64","term":"Seller","definition":"A seller lists and sells their own goods on Amazon's retail website. After an item is sold, it is either directly fulfilled by the seller using inventory managed by the seller, or fulfilled through the Fulfillment by Amazon (FBA) program, using the seller's FBA inventory."},{"_id":"67f83b34e8cff10031804d2a","term":"Vendor","definition":"A vendor supplies the inventory that is sold by Amazon on Amazon's retail website. There are two main types of vendors: retail procurement vendors and direct fulfillment vendors."},{"_id":"67f83b6ab654650025ba7811","term":"Retail procurement vendor","definition":"A vendor who sells inventory to Amazon and ships it to Amazon's fulfillment centers. Amazon then sells and ships the inventory to customers who make purchases on Amazon's retail website. A retail procurement vendor can be a brand owner or a distributor. In some cases, they manage the listings of the products that they supply to Amazon."},{"_id":"67f83b9010f8180014e4f302","term":"Direct fulfillment vendor","definition":"A vendor who ships orders to customers on Amazon's behalf. After a customer makes a purchase from Amazon's retail website, the direct fulfillment vendor ships the order directly to the customer."},{"_id":"67f83bb4bdd38e006a0cc703","term":"Public application","definition":"An application that is publicly available and is authorized by a selling partner."},{"_id":"67f83bd70d6bb30074c36627","term":"Private application","definition":"A self-authorized application that is available only to your organization."},{"_id":"67f83bf548f8ac0010636b8e","term":"Public developer","definition":"A developer who builds and offers publicly available applications that are used by other companies."},{"_id":"67f83c0f127d27001ea473d9","term":"Private developer","definition":"A developer who builds applications that integrate their own company with Amazon APIs."},{"_id":"67f94c2deabd850030c0df6e","term":"Rate limit","definition":"The maximum number of requests that you can make to an SP-API operation per second. To avoid throttling, stay below this limit."},{"_id":"67f94c81536dd100622897a5","term":"Burst limit","definition":"The maximum number of requests to an SP-API operation that you can build up over time and then submit simultaneously."},{"_id":"67f94cbe3ea4e452060b3037","term":"Usage plan","definition":"The combination of rate limit and burst limit that applies to a specific operation."},{"_id":"67f94cf8ae737000104fe9d5","term":"Token bucket algorithm","definition":"The algorithm that SP-API uses to rate-limit requests, based on an analogy of exchanging tokens for API requests."},{"_id":"67f94d57e9c75e0067fb1644","term":"Throttling","definition":"The act of SP-API temporarily rejecting your requests when you exceed your rate limit. A throttled request results in a 429 HTTP error response. You can retry throttled requests later."},{"_id":"67f94dbef4fa7600186fd714","term":"Account","definition":"The selling partner account on whose behalf the developer application calls the SP-API. You specify the account by providing a 'sellerId' when you call certain SP-API operations."},{"_id":"67f94e635080ab0030ce44cb","term":"Application","definition":"The developer application that calls SP-API on behalf of a selling partner. In the selling partner developer console, you can find the application ID after the application name."},{"_id":"67f94eab8a2fa5001e566f1a","term":"Grantless operation","definition":"Operations that don't require a `sellerId` as part of the request."},{"_id":"67f97be5927a6b0030494f29","term":"Featured offer","definition":"An offer for a product that Amazon displays on the product detail page with an 'Add to Cart' button."},{"_id":"67f97d20472bcf000fb747cd","term":"Featured offer expected price","definition":"A computed listing price at or below which a seller can expect to become the featured offer (before applicable promotions)."},{"_id":"67f97d5c2191d600684d1a4b","term":"Competing featured offer","definition":"An offer that might become featured if the target offer is priced higher than the featured offer expected price (FOEP)."},{"_id":"67f97d93da46d70011598708","term":"Current featured offer","definition":"An offer that has been selected as the featured offer."},{"_id":"67f97de7ad7efc0020d9f313","term":"Inbound order","definition":"Instructs the movement of inventory from an arbitrary location to an AWD distribution center. An inbound order has one or more inbound shipments. Each inbound shipment represents a trackable movement provided by an underlying transportation carrier."},{"_id":"67f97e36a8a08a0012b563ad","term":"Inbound shipments","definition":"Inbound shipments include a list of items that are contained within the shipment, and other details, such as: tracking number, carrier information, quantities received, expiration dates, preparation details, and your item label preparation preferences."},{"_id":"67f97fae43cb9e0025a1ddda","term":"Inventory listing","definition":"Contains SKU-level quantities for all inventory in an AWD distribution center."},{"_id":"67f980709b79db003643ff6f","term":"Credential rotation","definition":"The process of creating a new client secret and invalidating your old client secret."},{"_id":"67f980fdca0275003ddd8299","term":"Purchase order","definition":"A commercial document, issued by Amazon to a vendor or supplier, that authorizes the purchase of goods or services."},{"_id":"67f981282d76c900123df395","term":"Order acknowledgement","definition":"When a vendors accepts or rejects a purchase order sent by Amazon for fulfillment."},{"_id":"67f98159dda0cc0019e4928d","term":"Shipping label","definition":"A label provided by Amazon that vendors use when shipping orders directly to customers. The label contains the customer's shipping address, order details, and any special handling instructions provided by Amazon."},{"_id":"67f981ad765d0e0037b6238c","term":"Shipment confirmation","definition":"Allows Amazon to efficiently track vendor shipments and inform customers. Shipment confirmations contain information about the items being shipped, including purchase order number, ship date, estimated delivery date, and tracking number."},{"_id":"67f981e1446c08003d8253a9","term":"Invoice","definition":"A billing document that vendors provide to Amazon for the products they supply. For each purchase order vendors fulfill, they generate and submit invoices to Amazon. The invoice typically includes information such as the purchase order number, item details, pricing, taxes and the total amount due."},{"_id":"67f9821e976ad4006f46503a","term":"Amazon Standard Identification Number","definition":"A unique number that identifies an item in the Amazon catalog. Abbreviated as ASIN."},{"_id":"67f982816109ef004b36a824","term":"Variation","definition":"Every color or size for a catalog item represents a variation. Each variation is assigned a different ASIN and these are grouped together as variations of one parent ASIN."},{"_id":"67f982f8927a6b00304962ed","term":"SKU","definition":"A selling partner-supplied stock keeping unit (SKU) that identifies a listing. Data from one or more listings are reconciled into items in the Amazon catalog."},{"_id":"67f9835f785e74003090a87f","term":"URL encoding","definition":"Converts characters into a format that can be transmitted over the internet."},{"_id":"67f983a990b2d000606f1953","term":"KTYPE","definition":"A numeric identifier that is associated with a vehicle definition (brand, model, type, year). KTYPEs are used by various brands to link their products."},{"_id":"67f9840bd27a1b00119673bd","term":"GraphQL","definition":"GraphQL is a query language for APIs that enables clients to request and receive data in a single request. GraphQL provides efficient dynamic report generation and advanced filtering and querying capabilities."},{"_id":"67f98456765d0e0037b62c83","term":"Queries","definition":"Queries are structured requests made to databases or APIs to retrieve specific information based on defined criteria, facilitating data retrieval, manipulation, and filtering."},{"_id":"67f991d94ee8b30010a86905","term":"Pagination","definition":"Pagination involves breaking down a large set of results into manageable chunks or pages, with 'nextToken's serving as markers to sequentially navigate through these pages."},{"_id":"67f99242e3de700024bec95d","term":"Schema Explorer","definition":"The Data Kiosk Schema Explorer provides a user-friendly interface for visualizing and navigating through the structure and relationships of data schemas. It helps users build queries easily and better understand the underlying data."},{"_id":"67f992940d766c003d5d398a","term":"JSONL","definition":"JSON Lines is a format for storing structured data, where each line represents a separate JSON object. JSONL facilitates data processing and streaming."},{"_id":"67f992e51d460d0037bdd260","term":"Amazon S3 presigned URL","definition":"A URL for an S3 bucket from which you can download an object without AWS security credentials or permissions. In some cases the object can be compressed, in which case 'compressionAlgorithm' is returned in addition to the URL. The URL expires after five minutes."},{"_id":"67f99309178418000fea600b","term":"Amazon-partnered carrier","definition":"A carrier who has partnered with Amazon to provide discounted shipping rates."},{"_id":"67f993321c63560010f7b5f2","term":"Non-Amazon-partnered carrier","definition":"A carrier who has not partnered with Amazon to provide discounted shipping rates."},{"_id":"67f9935d14ccd00052c81658","term":"Small parcel shipment","definition":"Units packed in individual boxes that are individually labeled for delivery."},{"_id":"67f993b2172e000012bb170d","term":"Less Than Truckload","definition":"Less Than Truckload / Full Truckload (LTL / FTL) shipments combine individual boxes on pallets for delivery. The truck might contain shipments to other destinations."},{"_id":"67f993d78aabaa005306af06","term":"SEFAZ","definition":"The Brazilian tax authority (Secretaria da Fazenda do Brasil)."},{"_id":"67f99487f1af0d0030f84975","term":"Amazon EventBridge","definition":"A serverless event bus that connects application data from your own applications, integrated Software-as-a-Service (SaaS) applications, and AWS services."},{"_id":"67f994c76cbb7e0063f2e0ae","term":"Amazon Simple Queue Service","definition":"Amazon SQS is a fully managed message queuing service for microservices, distributed systems, and serverless applications."},{"_id":"67f995128b4a490011f5cfea","term":"Partner event source","definition":"Used by an AWS partner to send events to an AWS customer account. To receive these events, the customer must associate an event bus with the partner event source."},{"_id":"67f9953a0d766c003d5d3abf","term":"Event bus","definition":"Receives events from a source and routes them to target resources according to rules associated with the event bus."},{"_id":"67f9956b5908f6005a45a857","term":"Regulated product","definition":"A product that is sold on Amazon that requires additional information, provided at the time of purchase, to comply with local regulations."},{"_id":"67f99586469e120018355268","term":"Regulated information","definition":"Additional information that a customer must include when they purchase a regulated product."},{"_id":"67f995a97848a6005a787e46","term":"Regulated order","definition":"A customer order that contains a regulated product, and the associated regulated information."},{"_id":"67f995e67848a6005a787e93","term":"Restricted Data Token","definition":"A short-lived access token that authorizes calls to restricted operations. An RDT remains valid for one hour."},{"_id":"67f9961f5b506d00114e6246","term":"Verification status","definition":"The status of a regulated order, indicating whether it has been approved or rejected by a skilled professional."},{"_id":"67f99a481d460d0037bdd504","term":"Verification detail","definition":"Additional information about the verification of a regulated order. Supported details differ depending on the product. Some products might not support additional details. Only prescription-related details are currently supported in the US."},{"_id":"67f99a7a9fc994004309b6ab","term":"Listings item","definition":"Represents an item in a selling partner catalog that is uniquely identified by a selling partner-provided SKU. It also represents the product facts and sales terms for an item sold on or fulfilled by Amazon."},{"_id":"67f99ad5178418000fea675d","term":"Replenishment program","definition":"A program that offers the recurring delivery of a replenishable item at a frequency that is chosen by the recipient."},{"_id":"67f99afe9af17200363c4662","term":"Subscribe & Save","definition":"An Amazon replenishment program that provides recurring delivery (automatic or manual) of any replenishable item at a frequency chosen by the customer."},{"_id":"67f99b53ae0e03001813341e","term":"Offer","definition":"A replenishable offer, which is different from a listings offer. A replenishable offer is uniquely identified in the backend service by Amazon Standard Identification Number (ASIN), selling partner ID, marketplace ID, and SKU."},{"_id":"67f99b7aa9d0190030eb46d6","term":"Enabled offer","definition":"A replenishment program offer that is eligible for new subscriptions."},{"_id":"67f99c635b506d00114e79f3","term":"Restricted operation","definition":"An operation that returns restricted data, such as PII. You need an RDT to call a restricted operation."},{"_id":"67f99c8129104d005339c532","term":"Restricted resource","definition":"An HTTP method and path that represent a restricted operation."},{"_id":"67f99cd3ebdd6d000fda42a9","term":"Restricted report type","definition":"A report type that contains PII."},{"_id":"67f99cf89fb383007571b190","term":"Delegator application","definition":"An application that gets an RDT and passes it to a delegatee application. The selling partner authorizes and interacts with the delegator application."},{"_id":"67fd5f00f5fa720012f36a2d","term":"Shipping service","definition":"A carrier’s shipping service, such as UPS Ground or FedEx Standard Overnight, that is identified with a 'ShippingServiceId' value (returned by the 'getEligibleShipmentServices' operation)."},{"_id":"67fd652af5fa720012f375c5","term":"Shipping service offer","definition":"A shipping service offer made by a carrier. This is represented by the 'ShippingService' datatype and identified with a 'ShippingServiceOfferId' value, which is returned by the 'getEligibleShipmentServices' operation."},{"_id":"67fd655dbb47d7006ba654e3","term":"Package","definition":"A parcel that you want a carrier to ship. The package parameter includes metadata, such as dimensions, weight, and item contents."},{"_id":"67fd676eb48915005f3b7ca7","term":"Shipment","definition":"A package and shipping label. A shipment is identified with a 'ShipmentId' value."},{"_id":"67fd67d999098b00250c459e","term":"Additional seller inputs","definition":"Additional seller-provided information that is required to purchase certain shipping services. You can call the 'getAdditionalSellerInputs' operation to find out which additional seller inputs are required for a specific shipping service. After you get these additional seller inputs from the seller, you can use the inputs for the 'createShipment' operation to purchase the shipping service."},{"_id":"67fd6858ea08e800118ef70b","term":"Benefits","definition":"An object that contains a list of included and excluded Amazon benefits for a shipping service offer. Each excluded benefit has a list of reason codes for why it is excluded."},{"_id":"67fd68aec0ddce0044500320","term":"Delegatee application","definition":"An application that gets authorization to call restricted operations from an RDT that is passed to it by a delegator application. A delegatee application performs a specialized function that requires PII, such as shipping, tax invoicing, or tax remittance services, and is not directly authorized by the selling partner."},{"_id":"67fd6911fd5f5500253fe7da","term":"Specific path","definition":"A path in a restricted resource that contains a specific order or shipment identifier. For example, 'orders/v0/orders/902-3159896-1390916/address'."},{"_id":"67fd694637c849001279ee56","term":"Generic path","definition":"A path in a restricted resource that contains a generic identifier, such as '{orderId}' or '{shipmentId}'. For example, 'orders/v0/orders/{orderId}/address'."},{"_id":"67fd69996705dd00374a26e0","term":"Catalog item","definition":"Represents an item in Amazon's catalog that is uniquely identified by an ASIN. Data from one or more selling partner listings items are reconciled into a single item in Amazon's catalog and represents the product facts for an item sold on Amazon."},{"_id":"67fd6a173e3d0f000f99e553","term":"JSON schema","definition":"JSON is the serialization format that is used by the APIs, notifications, and feed formats described in this guide. JSON schema is a vocabulary for annotating, describing, and validating JSON content."},{"_id":"67fd6eb194367e00528ab7a5","term":"Variation family","definition":"A collection of similar items that vary by color, size, or other attributes, which is used to provide a single detail page experience for buyers on Amazon. Each unique combination of color, size, and style is represented by a separate item within the variation family. For example, a clothing article that is sold in multiple colors, sizes, and styles."},{"_id":"67fd6f10885bd80053cbb04b","term":"Listing","definition":"An item, identified by a SKU, that a selling partner has listed for sale on Amazon. Product facts included in Amazon listings are reconciled into Amazon catalog items, which are identified by ASINs."},{"_id":"67fd711b69b89a006ae3f689","term":"Full update","definition":"A full update to an Amazon listing results in full data requirements validation on the submitted data and either creates a new listing or replaces the data for an existing listing."},{"_id":"67fd722dd08cf4002b8fede0","term":"Partial update","definition":"A partial update to an Amazon listing results in partial data requirements validation for the specified attributes and updates one or more attributes for an existing listing."},{"_id":"67fd7282e4ece6006aaa7fb2","term":"Product type","definition":"A hierarchal categorization of items in the Amazon catalog. Item data requirements are tied to the item's associated product type."},{"_id":"67fd731e2ac12d005ef87c49","term":"XML schema","definition":"XML is the serialization format used by some listings feed types. XML schema (XSD) is the specification for describing and validating XML content."},{"_id":"67fd736caf6c8000188de32a","term":"Category XSD","definition":"Defines the category-specific data modeling for 'POST_PRODUCT_DATA' XML feed submissions."},{"_id":"67fd73d5f9066c001fa4ac00","term":"Fulfilled by Amazon","definition":"Items that are sold on Amazon and fulfilled by Amazon."},{"_id":"67fd7440da303c000f021479","term":"Merchant Fulfillment Network","definition":"Items that are sold on Amazon and fulfilled by the seller."},{"_id":"67fd7483915b74005bad1264","term":"Restriction","definition":"A condition that prevents the creation of a listing. In some instances, the restriction is due to an approval requirement, in which case additional steps might be available to apply for approval."},{"_id":"67fd74d7abc826002a78eb6a","term":"Meta schema","definition":"Describes the vocabulary that is used by JSON schema documents. For example, Amazon product type schemas include vocabulary for `selectors` and `editable`. This vocabulary is described in a meta schema, which enables libraries and applications to understand and validate JSON data based on these extensions to the standard JSON schema vocabulary."},{"_id":"67fd7514bb47d7006ba677cf","term":"Primary account user","definition":"A primary user, also known as the account administrator or owner, is the person who registers a new account. The primary user has access to every page and feature that their account type offers. This role can’t be granted or revoked, but it has the ability to grant or revoke the access of other users."},{"_id":"67fd753f61dfd10075331a37","term":"Secondary account user","definition":"A secondary user is invited by the primary user, through 'User Permissions'. A primary user can grant certain permissions to a secondary user. By setting user permissions, other users can complete tasks (such as manage inventory or handle shipping confirmations)."},{"_id":"67fd755f7a4016002447e138","term":"Authorized partner","definition":"An authorized partner is an individual or company to whom a seller has granted access to their account. Authorized partners only have access to the data that sellers grant. All external contractor or companies that are not part of a seller's company must be added as authorized partners. Do not add them as secondary account users."},{"_id":"67fd7596315d4000458da6c8","term":"Service provider","definition":"Third-party individuals and entities that are officially recognized by Amazon to help Amazon partners with day-to-day management and specialized aspects of operating their business with Amazon."},{"_id":"67fd75b426e063007c68364a","term":"Seller account employee","definition":"Works directly for one seller and manages only that seller’s account."},{"_id":"67fd75f1bd609e0057d40052","term":"Service provider account administrator","definition":"Manages access permissions and administrative functions for a third-party service provider business account and its employees."},{"_id":"67fd76110c5a35001aefbe9d","term":"Service provider employee","definition":"Works for a third-party service provider business and typically manages multiple sellers accounts on behalf of the service provider business."},{"_id":"67fd7a0c3ce304006902b3fd","term":"Personally identifiable information","definition":"Information that, when used alone or with other relevant data, can identify an individual."},{"_id":"67fd7a2f5266d8004c22032a","term":"Data retention","definition":"The process of storing data for compliance or business reasons."},{"_id":"67fd7a5275766c001b3bbe83","term":"Data retention period","definition":"The amount of time that an organization stores a particular type of data. Different data types should have different retention periods."},{"_id":"67fd7a82fdebcc0038808768","term":"Archiving","definition":"The process of moving data that is no longer being used to a separate storage device or location (such as cold storage) for retention."},{"_id":"67fd7abfbf4dfd0036c4b5af","term":"Cold storage","definition":"A storage medium for inactive and infrequently accessed data."},{"_id":"67fd7ae7bee6e20011b258d1","term":"Backup","definition":"A copy of data made in case something happens to the original. When a policy is applied to that backup copy, it is known as backup data retention."},{"_id":"67fd7b0a915b74005bad2fa8","term":"Destruction","definition":"Physical or technical destruction of data that makes it irretrievable by ordinary commercially available means."},{"_id":"67fd8054d9d1690064ad1340","term":"Identity and Access Management","definition":"A security framework that controls who can access an organization's technology resources."},{"_id":"67fd818732288f0068873556","term":"AWS Region","definition":"A physical location in the world where we have multiple Availability Zones. Availability Zones consist of one or more discrete data centers, each with redundant power, networking, and connectivity, housed in separate facilities."},{"_id":"67fe950ae4ff590011a1dd0f","term":"Access token","definition":"A short-lived credential that your application uses to make SP-API calls on behalf of a selling partner."},{"_id":"67fe9739019d03001e395844","term":"Authorization code","definition":"A short-lived token that your application exchanges for access and refresh tokens."},{"_id":"68102aa3a1ec1400675f549e","term":"ASIN","definition":"The Amazon Standard Identification Number. A unique number that identifies an item in the Amazon catalog."},{"_id":"681923ac9b75b400115008f2","term":"Amazon Transportation Services","definition":"Consists of carriers that are operated by Amazon. Amazon Transportation Services (ATS) is the segment of Amazon's transportation network that connects our fulfillment centers to delivery stations and post offices."},{"_id":"681a5bcec9cd4300540d75d7","term":"Amazon Easy Ship","definition":"A delivery service for Amazon sellers in select marketplaces."},{"_id":"68434bcd24845b00121fcd7c","term":"Browse node","definition":"A named location in the Amazon product catalog hierarchy that is used for navigation, product classification, and website content."},{"_id":"6852fd579ab69200443445b8","term":"App notification","definition":"The message that is displayed on the notifications banner in Seller Central. Each app notification consists of a notification template and can optionally include dynamic notification parameters."},{"_id":"6852fd7772d9f7002a834db0","term":"App notification template","definition":"A template that contains static content and dynamic parameter placeholders."},{"_id":"6852fda22eff28006c081288","term":"App notification parameter","definition":"A dynamic parameter that is required to fully construct an app notification template."},{"_id":"6852fdc929ca7a0043015789","term":"App template type","definition":"A unique identifier for your app notification template."},{"_id":"68d1c984bac09c867bb0a448","term":"WMS POS","definition":"Warehouse management system / Point of sale. The integration of the software that manages a warehouse and the software that manages sales."}],"graphqlSchema":"","gracePeriod":{"enabled":false,"endsAt":null},"healthCheck":{"provider":"","settings":{}},"i18n":{"defaultLanguage":"en","languages":[{"code":"en","type":"manual"}],"state":"enabled"},"intercom":"","is_active":true,"branchSharing":"enabled","internal":"","jwtExpirationTime":0,"landing_bottom":[],"llms_txt":true,"llms_txt_options":{"split":false,"split_categories":false,"query":null,"use_custom":null},"mcp":{"state":"disabled"},"mdxishMigrationStatus":{},"metrics":{"monthlyLimit":0,"monthlyPurchaseLimit":0,"thumbsEnabled":false,"meteredBilling":{}},"modules":{"landing":true,"docs":true,"examples":true,"reference":true,"graphql":false,"changelog":true,"discuss":true,"suggested_edits":false,"custompages":false,"tutorials":false},"name":"Amazon-Services-API","nav_names":{"docs":"","reference":"","changelog":"","discuss":"","recipes":"","tutorials":""},"oauth_url":"","onboardingCompleted":{"api":false,"appearance":false,"documentation":false,"domain":false,"jwt":false,"logs":false,"metricsSDK":false,"aiReady":false,"team":false,"gitSync":false},"openapiVisibility":"admin","owlbot":{"copilot":{"enabled":false,"hasBeenUsed":false,"installedCustomPage":""},"enabled":false,"newExperience":false,"v2":false,"isPaying":false,"exampleQuestions":{"question1":"","question2":"","question3":""},"customization":{"tone":"neutral","customTone":"","answerLength":"long","forbiddenWords":"","defaultAnswer":"","showAiDisclaimer":false,"showInSearch":true,"advancedInstruction":"","advancedModeEnabled":f