nds to dark/system mode via ReadMe's mixin) */\n.hub-is-home .undefined.container {\n background: var(--color-bg-page);\n width: 100%;\n}\n\n/* ============================================================\n FONTS\n ============================================================ */\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Rg.ttf);\n font-weight: normal;\n font-style: normal;\n}\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Bd.ttf);\n font-weight: bold;\n font-style: bold;\n}\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_RgIt.ttf);\n font-weight: italic;\n font-style: italic;\n}\n\n/* ============================================================\n BASE VARIABLES & TYPOGRAPHY\n ============================================================ */\n\nbody {\n --font-family: Ember, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto,\n Oxygen, Ubuntu, Cantarell, Fira Sans, Droid Sans, Helvetica Neue, sans-serif;\n --font-weight: 400;\n --font-weight-bold: 700;\n --border-radius: 8px;\n --spruce: #067D62; /* success green */\n --lake: #1196AB; /* info blue */\n --pacific: #007185; /* link blue (light mode) */\n --river: #3DB7CC; /* link blue (dark mode) */\n --thermal: #C5882D; /* caution orange-yellow */\n --tomato: #CC0C39; /* warning red */\n --platinum: #F0F2F2; /* alternate background */\n --off-white: #F3F5EF;\n --markdown-font-size: 16px;\n color: #16191f;\n}\n\n.markdown-body {\n --markdown-font-size: 16px;\n}\n\n/* ============================================================\n LINKS\n Light mode: Amazon --pacific.\n Dark + system dark: Amazon --river.\n ============================================================ */\n\n.markdown-body a,\n.toc-children a {\n color: var(--pacific) !important;\n}\n\n[data-color-mode=\"dark\"] .markdown-body a,\n[data-color-mode=\"dark\"] .toc-