t-weight-bold: 700;\n --border-radius: 8px;\n --spruce: #067D62; /* success green */\n --lake: #1196AB; /* info blue */\n --pacific: #007185; /* link blue (light mode) */\n --river: #3DB7CC; /* link blue (dark mode) */\n --thermal: #C5882D; /* caution orange-yellow */\n --tomato: #CC0C39; /* warning red */\n --platinum: #F0F2F2; /* alternate background */\n --off-white: #F3F5EF;\n --markdown-font-size: 16px;\n}\n\nbody,\n.rm-ReadMe {\n font-family: var(--font-family-body);\n}\n\n/* ReadMe explicitly assigns heading typography via --font-family-heading.\n Keep this rule so headings remain Ember even if component styles change. */\n.rm-ReadMe h1,\n.rm-ReadMe h2,\n.rm-ReadMe h3,\n.rm-ReadMe h4,\n.rm-ReadMe h5,\n.rm-ReadMe h6 {\n font-family: var(--font-family-heading);\n}\n\nbody {\n color: #16191f;\n}\n\n.markdown-body {\n --markdown-font-size: 16px;\n}\n\n/* ============================================================\n LINKS\n Light mode: Amazon --pacific.\n Dark + system dark: Amazon --river.\n ============================================================ */\n\n.markdown-body a,\n.toc-children a {\n color: var(--pacific) !important;\n}\n\n[data-color-mode=\"dark\"] .markdown-body a,\n[data-color-mode=\"dark\"] .toc-children a {\n color: var(--river) !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body a,\n [data-color-mode=\"system\"] .toc-children a {\n color: var(--river) !important;\n }\n}\n\n/* ============================================================\n DETAILS / SUMMARY\n Uses ReadMe's --color-bg-page-muted token — auto-responds\n to dark/system mode via ReadMe's own mixin.\n ============================================================ */\n\n.field-description details summary,\n.markdown-body details summary {\n text-decoration: underline;\n}\n\n/* Scoped to authored content on purpose. A bare `details` selector used to\n live here, which also painted ReadMe's own \u003cdetails> in the API reference\n params —