/\n.TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: #eef2f7;\n color: #3b4450;\n border-color: #e0e6ef;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(255, 255, 255, 0.06);\n color: var(--color-text-muted);\n border-color: rgba(255, 255, 255, 0.12);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(255, 255, 255, 0.06);\n color: var(--color-text-muted);\n border-color: rgba(255, 255, 255, 0.12);\n }\n}\n\n/* Featured badge — always hidden */\n.TutorialCard-Status3fMf38SYMYKV.TutorialCard-Status_featured3V5303ZsGONv {\n display: none !important;\n}\n\n/* ============================================================\n CODE SAMPLES PAGE - Hero + filter pills\n ============================================================ */\n\n.rf-Hero {\n max-width: 1100px;\n margin: 0 auto 18px;\n text-align: center;\n}\n\n.rf-Head h1 {\n margin: 0 0 6px;\n font-weight: 800;\n font-size: 44px;\n letter-spacing: -0.02em;\n /* color inherits from ReadMe's --color-text-default (auto dark-aware) */\n}\n\n.rf-Head p {\n margin: 0 0 14px;\n color: #6b7280;\n font-size: 18px;\n}\n\n[data-color-mode=\"dark\"] .rf-Head p {\n color: var(--color-text-muted);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Head p {\n color: var(--color-text-muted);\n }\n}\n\n/* --- Filter pills --- */\n\n.rf-Pills {\n display: flex;\n flex-wrap: wrap;\n gap: 22px;\n justify-content: center;\n padding: 10px 0 6px;\n}\n\n.rf-Pill {\n border: 1px solid #e5e7eb;\n background: #f6f7fb;\n padding: 14px 28px;\n border-radius: 999px;\n font-weight: 600;\n font-size: 16px;\n line-height: 1;\n transition: transform 0.06s ease, box-shadow 0.12s ease, background 0.12s;\n}\n\n[data-color-mode=\"dark\"] .rf-Pill {\n border-color: rgba(255, 255, 255, 0.12);\n background: var(--color-bg-page-muted);\n color: var(--color-text-default);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill {\n border-color: rgba(255, 255, 255, 0.12);\n background: var(--color-bg-page-muted);\n color: var(--color-text-default);\n }\n}\n\n.rf-Pill:hover {\n transform: translateY(-1px);\n box-shadow: 0 3px 10px rgba(16, 24, 40, 0.08);\n}\n\n[data-color-mode=\"dark\"] .rf-Pill:hover {\n box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill:hover {\n box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3);\n }\n}\n\n/* Active pill */\n.rf-Pill.is-active {\n background: #111;\n color: #fff;\n border-color: #111;\n}\n\n[data-color-mode=\"dark\"] .rf-Pill.is-active {\n background: #fff;\n color: #111;\n border-color: #fff;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill.is-active {\n background: #fff;\n color: #111;\n border-color: #fff;\n }\n}\n\n/* Hide filtered-out cards */\n.rf-hidden {\n display: none !important;\n}\n\n/* ============================================================\n DARK MODE — custom overrides only\n ──────────────────────────────────────────────────────────\n ReadMe's @include dark-mode mixin already handles:\n --color-bg-page, --color-bg-page-muted, --color-bg-overlay,\n --color-text-default, --color-border-default, inputs, etc.\n We only override Amazon-brand-specific values and anything\n ReadMe doesn't handle correctly on its own.\n Every rule appears in both [data-color-mode=\"dark\"] and the\n system @media block so both modes stay in sync.\n ============================================================ */\n\n/* --- Code block background --- */\n\n[data-color-mode=\"dark\"] pre {\n --md-code-background: #232F3E;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] pre {\n --md-code-background: #232F3E;\n }\n}\n\n/* --- Inline code background --- */\n\n[data-color-mode=\"dark\"] .markdown-body code {\n background-color: #3F4A59;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body code {\n background-color: #3F4A59;\n }\n}\n\n/* --- Code editor syntax (dark override for ADA contrast) --- */\n\n[data-color-mode=\"dark\"] .cm-s-neo .cm-string {\n color: #ffa07a !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .cm-s-neo .cm-string {\n color: #ffa07a !important;\n }\n}\n\n/* --- Callouts --- */\n\n[data-color-mode=\"dark\"] .markdown-body .callout { --background: white; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_error { --title: #e84747; --border: #e84747; --text: #e84747; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_warn { --title: #F0AD4E; --text: #F0AD4E; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_okay { --emoji: unset; --icon: \"✅\"; --border: #1ca51c; --text: #1ca51c; --title: #1ca51c; --icon-font-family: FontAwesome; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_info { --border: #5BC0DE; --text: #5BC0DE; --title: #5BC0DE; }\n[data-color-mode=\"dark\"] .markdown-body .callout[theme=\"⭐\"] { --background: #F7EDFA; --border: #B657CF; --text: #B657CF; --title: #B657CF; }\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body .callout { --background: white; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_error { --title: #e84747; --border: #e84747; --text: #e84747; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_warn { --title: #F0AD4E; --text: #F0AD4E; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_okay { --emoji: unset; --icon: \"✅\"; --border: #1ca51c; --text: #1ca51c; --title: #1ca51c; --icon-font-family: FontAwesome; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_info { --border: #5BC0DE; --text: #5BC0DE; --title: #5BC0DE; }\n [data-color-mode=\"system\"] .markdown-body .callout[theme=\"⭐\"] { --background: #F7EDFA; --border: #B657CF; --text: #B657CF; --title: #B657CF; }\n}\n\n/* --- Reference sidebar (API Reference area) --- */\n\n[data-color-mode=\"dark\"] .ThemeContext_dark .reference-redesign .rm-Sidebar {\n --Sidebar-link-background: #3F4A59 !important;\n}\n\n[data-color-mode=\"dark\"] .ThemeContext_dark .reference-redesign .rm-Sidebar a:hover {\n background-color: #232F3E !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .ThemeContext_dark .reference-redesign .rm-Sidebar {\n --Sidebar-link-background: #3F4A59 !important;\n }\n\n [data-color-mode=\"system\"] .ThemeContext_dark .reference-redesign .rm-Sidebar a:hover {\n background-color: #232F3E !important;\n }\n}\n\n/* ============================================================\n TRANSIFEX LANGUAGE PICKER — in-header styling\n\n GlobalJS moves Transifex's own #tx-live-lang-container into\n .rm-Header-right, strips .txlive-langselector-bottomleft (its\n dark floating pill), clears the inline colours it hard-codes on\n the toggle, then adds .rm-tx-inHeader. Everything below keys off\n that class, so it only applies once relocated — the default\n bottom-left widget is left untouched.\n\n Colours come from ReadMe's own tokens so light/dark follow the\n theme rather than being hard-coded.\n ============================================================ */\n\n.rm-Header-right .rm-tx-inHeader {\n position: relative !important;\n inset: auto !important;\n display: inline-flex;\n align-items: center;\n align-self: center; /* match the sibling nav links' vertical centring */\n flex: 0 0 auto; /* size to content; the group's gap does the spacing */\n width: -webkit-max-content !important;\n width: max-content !important;\n min-width: 0 !important;\n margin: 0;\n padding: 0;\n background: none !important;\n border: 0 !important;\n box-shadow: none !important;\n border-radius: 0 !important;\n z-index: 60;\n}\n\n/* ---- toggle ------------------------------------------------ */\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle {\n /* These match ReadMe's own header buttons exactly. From\n Header.f5ce1a113f3f421f7819.css:\n .rm-Header-top-link, .rm-Header-bottom-link {\n border: var(--border-width) solid rgba(0,0,0,0);\n font-size: 1em; height: 32px;\n padding: var(--Header-button-padding); }\n :hover { border-color: var(--Header-button-hover, var(--color-border-default)); }\n color: var(--Header-button-color)\n Earlier revisions guessed at 14px / 0 10px / --color-text-default, which\n is why it never lined up with Developer Hub. */\n display: inline-flex;\n align-items: center;\n justify-content: center;\n gap: 5px;\n height: 32px;\n margin: 0;\n /* Transifex sets `width: 100%` on the toggle (live.js). `auto` still let it\n stretch to the flex line, leaving dead space to the right of a short\n label like \"English\". max-content sizes the box to exactly its contents,\n so the border hugs the text at every language length. */\n width: -webkit-max-content !important;\n width: max-content !important;\n min-width: 0 !important;\n padding: 0 10px;\n font: inherit;\n font-size: 1em;\n font-weight: 400;\n /* line-height:1 gave a 14px line box; Transifex sets overflow:hidden on\n the toggle, which clipped the \"g\" descender. */\n line-height: 1.4;\n overflow: visible !important;\n letter-spacing: normal;\n text-transform: none;\n color: var(--Header-button-color) !important;\n background: transparent !important;\n /* Persistent border so it reads as a dropdown control, rather than the\n transparent one ReadMe uses for plain links. */\n border: var(--border-width, 1px) solid var(--color-border-default);\n border-radius: var(--border-radius, 6px);\n cursor: pointer;\n transition: background-color .15s ease, border-color .15s ease;\n}\n\n/* Globe icon in front of the language name, e.g. \"🌐 English\". Drawn as a\n ::before on the toggle rather than injected into the DOM: Transifex\n re-renders #tx-live-lang-current's textContent on every language switch\n (onTranslatePage), so anything we wrote directly into that node's text\n would be clobbered back to plain \"English\" on the next click. A CSS\n pseudo-element is immune to that — it never touches their text node.\n ::after is already the chevron, so this is ::before on the toggle itself,\n ahead of both the label and the marker in source order. The existing\n `gap: 5px` on the toggle's flex row spaces it automatically. */\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle::before {\n content: \"🌐\";\n flex: 0 0 auto;\n font-size: 1em;\n line-height: 1;\n}\n\n/* Transifex ships this on the label (from live.js):\n .txlive-langselector .txlive-langselector-current {\n float: left; padding: 0; max-width: 200px;\n overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n The float and overflow both have to go inside a flex row. */\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-current {\n float: none !important;\n display: inline-block;\n flex: 0 0 auto; /* never grow and push the chevron right */\n max-width: none !important;\n width: auto !important;\n padding: 0;\n line-height: 1.4;\n overflow: visible !important;\n text-overflow: clip;\n white-space: nowrap;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle:hover {\n border-color: var(--Header-button-hover, var(--color-border-default)) !important;\n background: var(--color-bg-hover, var(--color-bg-page-muted)) !important;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle:focus-visible {\n outline: 2px solid var(--color-primary);\n outline-offset: 2px;\n}\n\n/* Hide Transifex's own marker and draw the chevron on the toggle.\n Drawing it here rather than restyling .txlive-langselector-marker\n avoids inheriting that element's own box metrics, which is what\n made the first attempt render oversized and sitting below the\n text baseline. */\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-marker {\n display: none !important;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle::after {\n content: \"\";\n flex: 0 0 auto;\n width: 6px;\n height: 6px;\n border: solid currentColor;\n border-width: 0 1.5px 1.5px 0;\n /* rotate() alone keeps the box centred by the flex row; the small\n negative margin optically centres the rotated square, whose\n visual mass sits low. */\n transform: rotate(45deg);\n margin-top: -3px;\n opacity: .75;\n transition: transform .15s ease, opacity .15s ease;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle:hover::after {\n opacity: 1;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle[aria-expanded=\"true\"]::after {\n transform: rotate(-135deg);\n margin-top: 2px;\n opacity: 1;\n}\n\n/* ---- menu -------------------------------------------------- */\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list {\n position: absolute !important;\n top: calc(100% + 8px) !important;\n right: 0 !important;\n left: auto !important;\n bottom: auto !important;\n /* Transifex sets width:100% here too, which would pin the menu to the\n button's width and truncate \"Português (Brasil)\". Let it size to its\n own content but never be narrower than the button. */\n width: auto !important;\n min-width: 100%;\n max-height: 60vh;\n overflow-y: auto;\n margin: 0;\n padding: 6px;\n list-style: none;\n background: var(--color-bg-page);\n border: 1px solid var(--color-border-default);\n border-radius: 10px;\n box-shadow: 0 10px 24px rgba(0, 0, 0, .18), 0 2px 6px rgba(0, 0, 0, .10);\n z-index: 61;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list li {\n margin: 0;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list button {\n display: block;\n width: 100%;\n padding: 8px 10px;\n font: inherit;\n font-size: 14px;\n line-height: 1.2;\n text-align: left;\n color: var(--color-text-default);\n background: transparent;\n border: 0;\n border-radius: 6px;\n cursor: pointer;\n}\n\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list button:hover,\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list button:focus-visible {\n background: var(--color-bg-page-muted);\n outline: none;\n}\n\n/* Transifex marks the active language with .txlive-langselector-active\n on the li; aria-current is kept as a fallback if that changes. */\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list li.txlive-langselector-active button,\n.rm-Header-right .rm-tx-inHeader .txlive-langselector-list button[aria-current=\"true\"] {\n font-weight: 600;\n color: var(--color-primary);\n}\n\n/* Narrow screens: the Developer Hub / API Status / Support group is\n hidden, so keep the picker compact rather than crowding the search\n and theme toggle. */\n@media (max-width: 767px) {\n .rm-Header-right .rm-tx-inHeader .txlive-langselector-toggle {\n padding: 0 6px;\n font-size: 13px;\n }\n}\n/* ============================================================\n ADA COMPLIANCE FIX - Sidebar\n ============================================================ */\n\n/* Keep link + caret on one line */\n.rm-Sidebar .rm-sidebar-linkRow {\n display: flex;\n align-items: center;\n justify-content: space-between;\n gap: 4px;\n}\n\n.rm-Sidebar .rm-sidebar-linkRow > a.rm-Sidebar-link {\n flex: 1 1 auto;\n}\n\n.rm-Sidebar .rm-sidebar-linkRow > .Sidebar-link-buttonWrapper3hnFHNku8_BJ {\n flex: 0 0 auto;\n}\n\n/* Chevron rotation */\n.rm-Sidebar .rm-sidebar-linkRow i.Sidebar-link-expandIcon2yVH6SarI6NW {\n transition: transform 150ms ease;\n}\n\n.rm-Sidebar\n .rm-sidebar-linkRow\n i.Sidebar-link-expandIcon2yVH6SarI6NW.rm-sidebar-rotated {\n transform: rotate(90deg);\n}\n\n/* ============================================================\n HEADER NAV - Reorder items\n ============================================================ */\n\n/* ============================================================\n NEW API REF STYLES 2025\n ============================================================ */\n\n#reference-sidebar:not(.regenerated) .rm-Sidebar {\n opacity: 0 !important;\n pointer-events: none;\n}\n\n/* Remove headings on Ref section */\n#reference-sidebar h2.Sidebar-headingTRQyOa2pk0gh.rm-Sidebar-heading {\n display: none !important;\n}\n\n/* Welcome page top link */\n#reference-sidebar > div.Sidebar1t2G1ZJq-vU1.rm-Sidebar.hub-sidebar-content > section.Sidebar-listWrapper6Q9_yUrG906C.rm-Sidebar-section > ul > li > a {\n font-weight: bold !important;\n font-size: 16px !important;\n padding: 10px !important;\n margin-top: -15px !important;\n margin-bottom: 10px !important;\n margin-left: -10px !important;\n border-bottom: 1px solid black !important;\n border-radius: 0 !important;\n}\n\n/* Spinner overlay while sidebar regenerates */\n#reference-sidebar:not(.regenerated)::before {\n content: \"\";\n position: absolute;\n top: 50%;\n left: 50%;\n width: 2rem;\n height: 2rem;\n margin: -1rem 0 0 -1rem;\n border: 4px solid rgba(0, 0, 0, 0.1);\n border-top-color: #3b82f6;\n border-radius: 50%;\n animation: spin 0.8s linear infinite;\n z-index: 999;\n}\n\n@keyframes spin {\n to { transform: rotate(360deg); }\n}\n\n.reference-redesign .Sidebar-link2Dsha-r-GKh2 {\n padding: 5px 2px;\n}\n\n.reference-redesign .Sidebar-headingTRQyOa2pk0gh {\n padding-left: 0;\n}\n\n#reference-sidebar {\n overscroll-behavior: contain;\n}\n\n.reference-redesign.Nav3C5f8FcjkaHj {\n max-height: 87vh !important;\n flex: 0 0 330px !important;\n}\n\n#reference-sidebar h2.rm-Sidebar-heading {\n font-size: 15px !important;\n font-weight: 300 !important;\n padding: 5px 2px !important;\n margin-left: -7px !important;\n border-bottom: 1px solid #ececec !important;\n text-shadow: 0 0px 1px #d2d2d2 !important;\n cursor: pointer !important;\n}\n\n#reference-sidebar i.Sidebar-link-iconnjiqEiZlPn0W.Sidebar-link-expandIcon2yVH6SarI6NW.icon-chevron-rightward {\n display: none;\n}\n\n#reference-sidebar .Sidebar-link-buttonWrapper3hnFHNku8_BJ {\n display: none;\n width: 0;\n position: absolute;\n}\n\n.reference-redesign .Sidebar-link2Dsha-r-GKh2:active,\n.reference-redesign .Sidebar-link2Dsha-r-GKh2.active {\n background: #d8e6e980 !important;\n color: var(--Sidebar-link-color) !important;\n padding-left: 5px !important;\n margin-left: -5px !important;\n}\n\n/* ============================================================\n HEADER TOP\n Light mode: white background, default (dark) text.\n Dark + system dark: Amazon navy, white text/links/logo.\n ============================================================ */\n\n.rm-Header-top {\n background: white;\n}\n\n[data-color-mode=\"dark\"] .rm-Header-top {\n background: #232F3E;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rm-Header-top {\n background: #232F3E;\n }\n}\n\n/* White text/links/buttons only when header is dark */\n[data-color-mode=\"dark\"] .rm-Header-top,\n[data-color-mode=\"dark\"] .rm-Header-top a,\n[data-color-mode=\"dark\"] .rm-Header-top button,\n[data-color-mode=\"dark\"] .rm-Header-top .NavItem-textSlZuuL489uiw,\n[data-color-mode=\"dark\"] .rm-Header-top .Header-link2tXYTgXq85zW,\n[data-color-mode=\"dark\"] .rm-Header-top .Header-left-nav2xWPWMNHOGf_,\n[data-color-mode=\"dark\"] .rm-Header-top .rm-SearchToggle,\n[data-color-mode=\"dark\"] .rm-Header-top .rm-ThemeToggle {\n color: white !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rm-Header-top,\n [data-color-mode=\"system\"] .rm-Header-top a,\n [data-color-mode=\"system\"] .rm-Header-top button,\n [data-color-mode=\"system\"] .rm-Header-top .NavItem-textSlZuuL489uiw,\n [data-color-mode=\"system\"] .rm-Header-top .Header-link2tXYTgXq85zW,\n [data-color-mode=\"system\"] .rm-Header-top .Header-left-nav2xWPWMNHOGf_,\n [data-color-mode=\"system\"] .rm-Header-top .rm-SearchToggle,\n [data-color-mode=\"system\"] .rm-Header-top .rm-ThemeToggle {\n color: white !important;\n }\n}\n\n/* Logo: invert to white only when header is dark */\n[data-color-mode=\"dark\"] .rm-Header-top .rm-Logo-img,\n[data-color-mode=\"dark\"] .rm-Header-top .Header-logo-img3YvV4lcGKkeb {\n filter: brightness(0) invert(1);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rm-Header-top .rm-Logo-img,\n [data-color-mode=\"system\"] .rm-Header-top .Header-logo-img3YvV4lcGKkeb {\n filter: brightness(0) invert(1);\n }\n}\n\n/* Home page content area uses ReadMe's page bg token\n (auto-responds to dark/system mode via ReadMe's mixin) */\n.hub-is-home .undefined.container {\n background: var(--color-bg-page);\n width: 100%;\n}\n\n/* ============================================================\n FONTS\n ============================================================ */\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Rg.ttf);\n font-weight: normal;\n font-style: normal;\n}\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_Bd.ttf);\n font-weight: bold;\n font-style: bold;\n}\n\n@font-face {\n font-family: Ember;\n src: url(https://m.media-amazon.com/images/G/01/ember-fonts/AmazonEmber_RgIt.ttf);\n font-weight: italic;\n font-style: italic;\n}\n\n/* ============================================================\n BASE VARIABLES & TYPOGRAPHY\n ============================================================ */\n\nbody {\n --font-family: Ember, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto,\n Oxygen, Ubuntu, Cantarell, Fira Sans, Droid Sans, Helvetica Neue, sans-serif;\n --font-weight: 400;\n --font-weight-bold: 700;\n --border-radius: 8px;\n --spruce: #067D62; /* success green */\n --lake: #1196AB; /* info blue */\n --pacific: #007185; /* link blue (light mode) */\n --river: #3DB7CC; /* link blue (dark mode) */\n --thermal: #C5882D; /* caution orange-yellow */\n --tomato: #CC0C39; /* warning red */\n --platinum: #F0F2F2; /* alternate background */\n --off-white: #F3F5EF;\n --markdown-font-size: 16px;\n color: #16191f;\n}\n\n.markdown-body {\n --markdown-font-size: 16px;\n}\n\n/* ============================================================\n LINKS\n Light mode: Amazon --pacific.\n Dark + system dark: Amazon --river.\n ============================================================ */\n\n.markdown-body a,\n.toc-children a {\n color: var(--pacific) !important;\n}\n\n[data-color-mode=\"dark\"] .markdown-body a,\n[data-color-mode=\"dark\"] .toc-children a {\n color: var(--river) !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body a,\n [data-color-mode=\"system\"] .toc-children a {\n color: var(--river) !important;\n }\n}\n\n/* ============================================================\n DETAILS / SUMMARY\n Uses ReadMe's --color-bg-page-muted token — auto-responds\n to dark/system mode via ReadMe's own mixin.\n ============================================================ */\n\n.field-description details summary,\n.markdown-body details summary {\n text-decoration: underline;\n}\n\n.field-description details,\n.markdown-body details,\ndetails {\n background: var(--color-bg-page-muted);\n padding: 1rem;\n border-radius: var(--border-radius);\n}\n\n/* ============================================================\n TABLES\n --color-bg-page-muted auto-responds to dark/system mode.\n ============================================================ */\n\ntd {\n vertical-align: top !important;\n}\n\n.markdown-body table code {\n word-break: break-all !important;\n}\n\n.markdown-body table:not(.plain) tr:nth-child(2n) {\n background: var(--color-bg-page-muted);\n}\n\nthead {\n --table-head: var(--color-bg-page-muted);\n}\n\n/* ============================================================\n LISTS\n ============================================================ */\n\nli.RefinementList-Item1HVbdQ_il-QX {\n list-style-type: none !important;\n}\n\nol li {\n list-style-type: decimal;\n}\n\n.rm-Recipes ol li {\n list-style-type: inherit !important;\n}\n\n#Explorer ol li {\n list-style-type: none !important;\n}\n\n/* ============================================================\n CALLOUTS — light mode base\n ============================================================ */\n\n.callout code {\n display: inline-block;\n}\n\n.markdown-body .callout {\n --background: white;\n border: 3px solid;\n border-left: 12px solid;\n border-radius: var(--border-radius);\n}\n\n.markdown-body .callout[theme=\"⭐\"] {\n --border: #7b388d;\n border-color: #7b388d;\n --title: #7b388d;\n}\n\n.markdown-body .callout.callout_info {\n border-color: var(--lake);\n --title: var(--lake);\n}\n\n.markdown-body .callout.callout_error {\n border-color: var(--tomato);\n --title: var(--tomato);\n}\n\n.markdown-body .callout.callout_okay {\n border-color: var(--spruce);\n --title: var(--spruce);\n --emoji: unset;\n --icon: \"✅\";\n --icon-font-family: FontAwesome;\n}\n\n.markdown-body .callout.callout_warn {\n border-color: var(--thermal);\n --title: #80581d;\n}\n\n/* ============================================================\n CODE SAMPLES PAGE - Tutorial card & hero styles\n ============================================================ */\n\n/* Hide recipe hero banner */\nsection.TutorialHero3tJ8Cd5oYe9Y.rm-RecipeHero {\n display: none !important;\n}\n\n/* --- Typography --- */\n\n.TutorialCard-TopnKen9BUvK2xm .markdown-body {\n --markdown-font-size: 14px !important;\n}\n\n.TutorialCard-TopnKen9BUvK2xm .field-description ol,\n.TutorialCard-TopnKen9BUvK2xm .field-description ul,\n.TutorialCard-TopnKen9BUvK2xm .markdown-body ol,\n.TutorialCard-TopnKen9BUvK2xm .markdown-body ul {\n padding-left: 0 !important;\n list-style: none;\n}\n\n/* --- Card shell --- */\n\n.TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA {\n position: relative;\n border: 1px solid #e9e9ef;\n border-radius: 16px;\n background: #fff;\n box-shadow: 0 6px 20px rgba(16, 24, 40, 0.06);\n overflow: hidden;\n display: flex;\n flex-direction: column;\n isolation: isolate;\n}\n\n[data-color-mode=\"dark\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA {\n border-color: rgba(255, 255, 255, 0.1);\n background: var(--color-bg-page-muted);\n box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA {\n border-color: rgba(255, 255, 255, 0.1);\n background: var(--color-bg-page-muted);\n box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);\n }\n}\n\n/* Card hover */\n.TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA:hover {\n transform: translateY(-2px);\n box-shadow: 0 10px 24px rgba(16, 24, 40, 0.10);\n}\n\n[data-color-mode=\"dark\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA:hover {\n box-shadow: 0 10px 24px rgba(0, 0, 0, 0.4);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA:hover {\n box-shadow: 0 10px 24px rgba(0, 0, 0, 0.4);\n }\n}\n\n/* --- Tinted header band --- */\n\n.TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA::before {\n content: \"\";\n position: absolute;\n inset: 0 0 80% 0;\n background: #f3f4ff;\n z-index: 0;\n}\n\n[data-color-mode=\"dark\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA::before {\n background: rgba(255, 255, 255, 0.04);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialGrid26plsmAq5mws > .TutorialCard2XH0Nnhtx8xA::before {\n background: rgba(255, 255, 255, 0.04);\n }\n}\n\n/* --- Inner content --- */\n\n.TutorialCard-TopnKen9BUvK2xm {\n position: relative;\n z-index: 1;\n padding: 24px 20px 20px;\n display: flex;\n flex-direction: column;\n align-items: center;\n gap: 10px;\n text-align: center;\n}\n\n/* --- Emoji avatar --- */\n\n.TutorialCard-Avatar2GqJCrkbnRPc {\n width: 56px !important;\n height: 56px !important;\n border-radius: 27% !important;\n display: grid !important;\n place-items: center !important;\n box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08) !important;\n margin-bottom: 0;\n margin-top: 10px;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard-Avatar2GqJCrkbnRPc {\n box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4) !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard-Avatar2GqJCrkbnRPc {\n box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4) !important;\n }\n}\n\n/* --- Card title --- */\n\n.TutorialCard-Title3uoQf4kF9mQC {\n margin: 6px 0 0;\n font: 600 18px/1.25 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n color: #111827;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard-Title3uoQf4kF9mQC {\n color: var(--color-text-default);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard-Title3uoQf4kF9mQC {\n color: var(--color-text-default);\n }\n}\n\n/* --- Card description --- */\n\n.TutorialCard-Description2yaRK8FfwVRG {\n color: #6b7280;\n font-size: 14px;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard-Description2yaRK8FfwVRG {\n color: var(--color-text-muted);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard-Description2yaRK8FfwVRG {\n color: var(--color-text-muted);\n }\n}\n\n/* --- Steps (hidden) --- */\n\n.TutorialCard-Steps2mMaj5E6nS5t {\n display: none !important;\n}\n\n/* --- CTA button --- */\n\n.TutorialCard-Button3TbA37xdNo1S {\n margin-top: auto !important;\n width: 140px !important;\n align-self: center !important;\n border-radius: 10px !important;\n font-weight: 600 !important;\n background: transparent !important;\n border-color: #1d1ddd !important;\n color: #1d1ddd !important;\n box-shadow: 0 1px 0 rgba(0, 0, 0, 0.05) !important;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard-Button3TbA37xdNo1S {\n border-color: #92d6ff !important;\n color: #92d6ff !important;\n box-shadow: none !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard-Button3TbA37xdNo1S {\n border-color: #92d6ff !important;\n color: #92d6ff !important;\n box-shadow: none !important;\n }\n}\n\n/* --- Status badge --- */\n\n.TutorialCard-Status3fMf38SYMYKV {\n position: absolute;\n z-index: 2;\n top: 10px;\n right: 10px;\n background: #fff6d6;\n color: #7a5c00;\n border: 1px solid #f3e4a6;\n font-size: 12px;\n padding: 4px 8px;\n border-radius: 999px;\n display: flex;\n align-items: center;\n gap: 6px;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(250, 230, 100, 0.12);\n color: #e6c96a;\n border-color: rgba(250, 230, 100, 0.25);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(250, 230, 100, 0.12);\n color: #e6c96a;\n border-color: rgba(250, 230, 100, 0.25);\n }\n}\n\n/* Unpublished variant */\n.TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: #eef2f7;\n color: #3b4450;\n border-color: #e0e6ef;\n}\n\n[data-color-mode=\"dark\"] .TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(255, 255, 255, 0.06);\n color: var(--color-text-muted);\n border-color: rgba(255, 255, 255, 0.12);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .TutorialCard_unpublished29bfESQoG_-7 .TutorialCard-Status3fMf38SYMYKV {\n background: rgba(255, 255, 255, 0.06);\n color: var(--color-text-muted);\n border-color: rgba(255, 255, 255, 0.12);\n }\n}\n\n/* Featured badge — always hidden */\n.TutorialCard-Status3fMf38SYMYKV.TutorialCard-Status_featured3V5303ZsGONv {\n display: none !important;\n}\n\n/* ============================================================\n CODE SAMPLES PAGE - Hero + filter pills\n ============================================================ */\n\n.rf-Hero {\n max-width: 1100px;\n margin: 0 auto 18px;\n text-align: center;\n}\n\n.rf-Head h1 {\n margin: 0 0 6px;\n font-weight: 800;\n font-size: 44px;\n letter-spacing: -0.02em;\n /* color inherits from ReadMe's --color-text-default (auto dark-aware) */\n}\n\n.rf-Head p {\n margin: 0 0 14px;\n color: #6b7280;\n font-size: 18px;\n}\n\n[data-color-mode=\"dark\"] .rf-Head p {\n color: var(--color-text-muted);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Head p {\n color: var(--color-text-muted);\n }\n}\n\n/* --- Filter pills --- */\n\n.rf-Pills {\n display: flex;\n flex-wrap: wrap;\n gap: 22px;\n justify-content: center;\n padding: 10px 0 6px;\n}\n\n.rf-Pill {\n border: 1px solid #e5e7eb;\n background: #f6f7fb;\n padding: 14px 28px;\n border-radius: 999px;\n font-weight: 600;\n font-size: 16px;\n line-height: 1;\n transition: transform 0.06s ease, box-shadow 0.12s ease, background 0.12s;\n}\n\n[data-color-mode=\"dark\"] .rf-Pill {\n border-color: rgba(255, 255, 255, 0.12);\n background: var(--color-bg-page-muted);\n color: var(--color-text-default);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill {\n border-color: rgba(255, 255, 255, 0.12);\n background: var(--color-bg-page-muted);\n color: var(--color-text-default);\n }\n}\n\n.rf-Pill:hover {\n transform: translateY(-1px);\n box-shadow: 0 3px 10px rgba(16, 24, 40, 0.08);\n}\n\n[data-color-mode=\"dark\"] .rf-Pill:hover {\n box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3);\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill:hover {\n box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3);\n }\n}\n\n/* Active pill */\n.rf-Pill.is-active {\n background: #111;\n color: #fff;\n border-color: #111;\n}\n\n[data-color-mode=\"dark\"] .rf-Pill.is-active {\n background: #fff;\n color: #111;\n border-color: #fff;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .rf-Pill.is-active {\n background: #fff;\n color: #111;\n border-color: #fff;\n }\n}\n\n/* Hide filtered-out cards */\n.rf-hidden {\n display: none !important;\n}\n\n/* ============================================================\n DARK MODE — custom overrides only\n ──────────────────────────────────────────────────────────\n ReadMe's @include dark-mode mixin already handles:\n --color-bg-page, --color-bg-page-muted, --color-bg-overlay,\n --color-text-default, --color-border-default, inputs, etc.\n We only override Amazon-brand-specific values and anything\n ReadMe doesn't handle correctly on its own.\n Every rule appears in both [data-color-mode=\"dark\"] and the\n system @media block so both modes stay in sync.\n ============================================================ */\n\n/* --- Code block background --- */\n\n[data-color-mode=\"dark\"] pre {\n --md-code-background: #232F3E;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] pre {\n --md-code-background: #232F3E;\n }\n}\n\n/* --- Inline code background --- */\n\n[data-color-mode=\"dark\"] .markdown-body code {\n background-color: #3F4A59;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body code {\n background-color: #3F4A59;\n }\n}\n\n/* --- Code editor syntax (dark override for ADA contrast) --- */\n\n[data-color-mode=\"dark\"] .cm-s-neo .cm-string {\n color: #ffa07a !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .cm-s-neo .cm-string {\n color: #ffa07a !important;\n }\n}\n\n/* --- Callouts --- */\n\n[data-color-mode=\"dark\"] .markdown-body .callout { --background: white; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_error { --title: #e84747; --border: #e84747; --text: #e84747; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_warn { --title: #F0AD4E; --text: #F0AD4E; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_okay { --emoji: unset; --icon: \"✅\"; --border: #1ca51c; --text: #1ca51c; --title: #1ca51c; --icon-font-family: FontAwesome; }\n[data-color-mode=\"dark\"] .markdown-body .callout.callout_info { --border: #5BC0DE; --text: #5BC0DE; --title: #5BC0DE; }\n[data-color-mode=\"dark\"] .markdown-body .callout[theme=\"⭐\"] { --background: #F7EDFA; --border: #B657CF; --text: #B657CF; --title: #B657CF; }\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .markdown-body .callout { --background: white; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_error { --title: #e84747; --border: #e84747; --text: #e84747; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_warn { --title: #F0AD4E; --text: #F0AD4E; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_okay { --emoji: unset; --icon: \"✅\"; --border: #1ca51c; --text: #1ca51c; --title: #1ca51c; --icon-font-family: FontAwesome; }\n [data-color-mode=\"system\"] .markdown-body .callout.callout_info { --border: #5BC0DE; --text: #5BC0DE; --title: #5BC0DE; }\n [data-color-mode=\"system\"] .markdown-body .callout[theme=\"⭐\"] { --background: #F7EDFA; --border: #B657CF; --text: #B657CF; --title: #B657CF; }\n}\n\n/* --- Reference sidebar (API Reference area) --- */\n\n[data-color-mode=\"dark\"] .ThemeContext_dark .reference-redesign .rm-Sidebar {\n --Sidebar-link-background: #3F4A59 !important;\n}\n\n[data-color-mode=\"dark\"] .ThemeContext_dark .reference-redesign .rm-Sidebar a:hover {\n background-color: #232F3E !important;\n}\n\n@media (prefers-color-scheme: dark) {\n [data-color-mode=\"system\"] .ThemeContext_dark .reference-redesign .rm-Sidebar {\n --Sidebar-link-background: #3F4A59 !important;\n }\n\n [data-color-mode=\"system\"] .ThemeContext_dark .reference-redesign .rm-Sidebar a:hover {\n background-color: #232F3E !important;\n }\n}","js":"/* ============================================================================\n TRANSIFEX LIVE — stock widget\n ----------------------------------------------------------------------------\n Transifex renders and positions its own picker. We insert no DOM and touch\n no ReadMe component. This replaces the old code that relocated ReadMe's\n native language dropdown into the header, which cannot work now that that\n dropdown no longer exists.\n\n Why the defineProperty rather than a plain `window.liveSettings = {...}`:\n ReadMe injects its own liveSettings block with `picker: false` in a \u003cscript>\n that comes AFTER all custom JS in the document (~line 2580 of the rendered\n page). A plain assignment here is silently\n overwritten and the widget never appears. The accessor below merges whatever\n ReadMe assigns and removes `picker` so the default widget renders. Lives at\n GROUP level so it also covers the GLP, where ReadMe injects nothing at all.\n ========================================================================== */\n;(function () {\n var API_KEY = \"9251cba762e8402cae3a821b20521b05\";\n\n // `picker` is a CSS selector string (where to mount) or false (disable).\n // There is no `true`. The default floating picker renders when the key is\n // ABSENT, so we delete it rather than set it — ReadMe's injected block sets\n // `picker: false`, which is what was suppressing the widget.\n var settings = { api_key: API_KEY, dynamic: true };\n\n try {\n Object.defineProperty(window, \"liveSettings\", {\n configurable: true,\n enumerable: true,\n get: function () { return settings; },\n set: function (incoming) {\n settings = incoming || {};\n if (!settings.api_key) settings.api_key = API_KEY;\n delete settings.picker; // let Transifex render its own default picker\n settings.dynamic = true; // required: the hub is a React SPA\n }\n });\n } catch (e) {\n // Property already locked by something else — fall back to assignment.\n window.liveSettings = settings;\n }\n\n // Load live.js only if nothing else already has. ReadMe's injected block\n // loads it today; this fallback keeps the widget working if that record is\n // later turned off. Guarding on both the global and the tag avoids the\n // double-load that produced the duplicate pickers in the Transifex ticket.\n function ensureLive() {\n if (window.Transifex && window.Transifex.live) return;\n if (document.querySelector('script[src*=\"cdn.transifex.com/live.js\"]')) return;\n var s = document.createElement(\"script\");\n s.type = \"text/javascript\";\n s.async = true;\n s.src = \"//cdn.transifex.com/live.js\";\n document.head.appendChild(s);\n }\n\n if (document.readyState === \"loading\") {\n window.addEventListener(\"DOMContentLoaded\", function () { setTimeout(ensureLive, 0); });\n } else {\n setTimeout(ensureLive, 0);\n }\n\n /* --------------------------------------------------------------------------\n Relocate Transifex's picker into the header, left of \"Developer Hub\".\n Amazon asked for top-right rather than Transifex's default bottom-left.\n\n We move Transifex's OWN node (#tx-live-lang-container) into ReadMe's\n header. Note the direction: the old code did the reverse — it pulled\n ReadMe's native dropdown OUT of React's tree, which is what caused the\n \"removeChild\" crashes. Appending a foreign node INTO a React container is\n the safe direction; the only risk is React dropping it on re-render, which\n the observer below repairs.\n ----------------------------------------------------------------------- */\n var PICKER_ID = \"tx-live-lang-container\";\n var HEADER_SEL = \".rm-Header-right\"; // stable rm-* contract\n var ANCHOR_SEL = '[class*=\"Header-right_desktop\"]'; // hashed -> wildcard\n\n function placePicker() {\n var picker = document.getElementById(PICKER_ID);\n var header = document.querySelector(HEADER_SEL);\n if (!picker || !header) return false;\n\n // Sit INSIDE the Developer Hub / API Status / Support group, as its first\n // child. That group is its own flex row with gap:var(--xs), so being a\n // member of it lines the picker up with those links exactly. Inserting as\n // a sibling of the group instead left a large gap, because the picker then\n // sat in the outer .rm-Header-right row and did not share their spacing.\n var group = header.querySelector(ANCHOR_SEL);\n var target = group || header;\n\n // Already in the right place — re-assert styling, Transifex can re-add\n // its own class on re-render.\n if (picker.parentElement === target) { styleForHeader(picker); return true; }\n\n target.insertBefore(picker, target.firstChild);\n styleForHeader(picker);\n return true;\n }\n\n // Transifex ships a dark floating \"pill\" via .txlive-langselector-bottomleft\n // and hard-codes colours inline on the toggle. Rather than fight all of that\n // with !important, drop the positional class and clear the inline styles, so\n // our own header styling is the only thing applying.\n function styleForHeader(picker) {\n picker.classList.remove(\"txlive-langselector-bottomleft\");\n picker.classList.add(\"rm-tx-inHeader\");\n var toggle = picker.querySelector(\".txlive-langselector-toggle\");\n if (toggle) {\n toggle.style.removeProperty(\"background\");\n toggle.style.removeProperty(\"color\");\n toggle.style.removeProperty(\"letter-spacing\");\n toggle.style.removeProperty(\"text-transform\");\n }\n }\n\n var placeTimer;\n function schedulePlace() {\n clearTimeout(placeTimer);\n placeTimer = setTimeout(placePicker, 200);\n }\n\n // Cheap guard: two lookups per debounced batch, and it exits immediately\n // once the picker is already parented to the header.\n new MutationObserver(schedulePlace).observe(document.body, {\n childList: true,\n subtree: true\n });\n window.addEventListener(\"popstate\", schedulePlace);\n if (window.jQuery) { jQuery(window).on(\"pageLoad\", schedulePlace); }\n schedulePlace();\n\n /* --------------------------------------------------------------------------\n Put the chosen language into the ADDRESS BAR.\n\n Transifex translates in place and never touches the URL, so a Spanish\n reader has nothing to bookmark or send to a colleague. ReadMe still parses\n a `/lang-XX_XX/` segment on every project — it is a static Express route,\n not a per-project feature, so no dashboard flag turns it on or off — and\n templates the value into `paramLang`, which is exactly what the widget\n reads on load. Navigating to the prefixed URL therefore gives a real,\n shareable, bookmarkable language URL.\n\n Full navigation, NOT history.pushState: ReadMe's React app reads its\n baseUrl once at hydration. Rewriting the URL afterwards would leave the\n router on the old base and every client-side link would be built wrong.\n A real load lets it boot with the prefix, after which internal navigation\n stays inside the chosen language on its own.\n\n Editor preview is why search+hash are carried over verbatim. The Site\n panel frames the hub with `?isFramePreview=true`; dropping that param\n re-arms X-Frame-Options and the preview goes blank. We navigate\n `window.location` (this frame only) and never `window.top`, so clicking\n the picker inside the editor cannot yank the author out of the dashboard.\n ----------------------------------------------------------------------- */\n var LANG_SEG = /^lang-[a-z]{2}_[A-Z]{2}$/; // a path segment\n var LANG_CODE = /^[a-z]{2}_[A-Z]{2}$/; // a Transifex code\n // The prefix sits immediately BEFORE the section segment, which also places\n // it correctly after a version: /sp-api/v2.0/lang-es_ES/docs/...\n var SECTIONS = [\"docs\", \"reference\", \"changelog\", \"discuss\", \"page\", \"recipes\"];\n\n /* Are we inside the dashboard's Site panel rather than on the real site?\n\n Everything below rewrites URLs, and inside that iframe a real navigation\n can escape the frame and replace the whole editor — the nav items point at\n the developer-docs.amazon.COM alias while the frame is served from the\n bare .amazon gTLD, so following one is a cross-origin hop that the browser\n is free to break out of.\n\n The frame's URL is never visible to the author and never bookmarked, so a\n language prefix there buys nothing and risks the editing session. In the\n editor we leave every URL alone and let Transifex translate in place,\n which is all a preview needs. Public visitors are unaffected. */\n function inFramePreview() {\n try { if (window.top !== window.self) return true; } catch (e) { return true; }\n return /[?&]isFramePreview=/i.test(location.search);\n }\n\n // Flip to false to silence. Left on while we are still shaking this out.\n var TX_DEBUG = true;\n function txlog() {\n if (!TX_DEBUG || !window.console) return;\n var a = [\"%c[tx-lang]\", \"color:#0a7; font-weight:bold\"];\n for (var i = 0; i \u003c arguments.length; i++) a.push(arguments[i]);\n console.log.apply(console, a);\n }\n\n function pathForLang(pathname, code) {\n var parts = pathname.split(\"/\").filter(Boolean);\n parts = parts.filter(function (p) { return !LANG_SEG.test(p); });\n\n var at = -1;\n for (var i = 0; i \u003c parts.length; i++) {\n if (SECTIONS.indexOf(parts[i]) !== -1) { at = i; break; }\n }\n\n if (at === -1) {\n // No section segment. A PROJECT root takes the prefix on the end —\n // /sp-api -> /sp-api/lang-de_DE renders correctly, verified.\n //\n // The GROUP root must NOT. /lang-de_DE returns 200 and renders the\n // header and nav, but the landing-page body comes back EMPTY — the\n // group landing page does not support a language prefix. Generating\n // that URL would hand readers a blank page, so exactly one path\n // segment (the project slug) is required here.\n if (parts.length !== 1) return null;\n if (code) parts.push(\"lang-\" + code);\n return \"/\" + parts.join(\"/\");\n }\n\n if (code) parts.splice(at, 0, \"lang-\" + code);\n return \"/\" + parts.join(\"/\");\n }\n\n function sourceLang() {\n try {\n if (window.Transifex && Transifex.live && Transifex.live.getSourceLanguageCode) {\n return Transifex.live.getSourceLanguageCode() || \"en\";\n }\n } catch (e) {}\n return \"en\";\n }\n\n // Delegated + capture so it works no matter when Transifex renders the\n // picker, and so it runs before Transifex's own per-button click handler.\n // Markup is \u003cli>\u003cbutton data-value=\"es_ES\"> inside #tx-live-lang-container.\n document.addEventListener(\"click\", function (evt) {\n var opt = evt.target && evt.target.closest && evt.target.closest(\"[data-value]\");\n if (!opt || !opt.closest(\"#\" + PICKER_ID)) return; // not the picker\n\n var code = opt.getAttribute(\"data-value\");\n txlog(\"picker clicked:\", code, \"| path:\", location.pathname);\n\n if (!code) { txlog(\" -> SKIP: option had no data-value\"); return; }\n\n // The source language has no prefix, so English strips back to the plain\n // URL. Anything not in xx_XX form is treated the same way rather than\n // invented into a segment ReadMe would echo but nothing would translate.\n var src = sourceLang();\n var stripping = (code === src || !LANG_CODE.test(code));\n var target = stripping\n ? pathForLang(location.pathname, null)\n : pathForLang(location.pathname, code);\n\n txlog(\" source lang:\", src, \"| stripping:\", stripping, \"| target:\", target);\n\n if (!target) {\n txlog(\" -> SKIP: no safe place for the prefix in this path\");\n return;\n }\n if (target === location.pathname) {\n txlog(\" -> SKIP: already on that path\");\n return;\n }\n\n var dest = target + location.search + location.hash;\n\n // Transifex's own fallback reads this when no detectlang is supplied, so\n // the choice still survives if ReadMe ever stops injecting its block.\n try { localStorage.setItem(\"txlive:selectedlang\", code); } catch (e) {}\n\n if (inFramePreview()) {\n // Editor preview: do nothing to the URL. Not a navigation, not even a\n // replaceState. The frame's address is not the one in the author's\n // address bar anyway, so there is nothing to gain and a working editor\n // to lose. We do NOT preventDefault, so Transifex still translates the\n // page in place and the preview looks right.\n txlog(\" -> editor preview: URL left alone by design; Transifex will\",\n \"translate in place. URL rewriting is public-site only.\");\n return;\n }\n\n evt.preventDefault();\n evt.stopPropagation();\n\n txlog(\" -> NAVIGATING to\", dest);\n location.assign(dest);\n }, true);\n\n /* --------------------------------------------------------------------------\n Carry the language prefix across INTERNAL links.\n\n ReadMe's own relative nav links (/sp-api/docs, /sp-api/reference) already\n pick up the prefix from the router's baseUrl. Custom nav items entered as\n ABSOLUTE urls do not, and cannot — the router will not rewrite an absolute\n href. On this hub that is Models / Release Notes / FAQ, which is why\n clicking them dropped a Spanish reader back to English.\n\n This replaces the pre-2026-09-09 updateLinks() in ProjectJS.js, which\n could not have fixed those three anyway:\n - it selected `.rm-Article a, #content a, .Header-right\u003chash> a`, and\n the primary nav is Header-LEFT, so it never saw them;\n - its isSameDomain() compared hostnames exactly, and those links are on\n developer-docs.amazon.COM while the hub serves as developer-docs.amazon\n — different hostnames, so they failed the check and were skipped;\n - it keyed off a build-hashed class, which churns every build.\n It also folded in /page/->/docs/ rewriting and a hardcoded redirect map.\n Redirects.txt owns that now, so none of it is carried over.\n\n We rewrite href in place rather than intercepting clicks, so copy-link,\n middle-click and open-in-new-tab all carry the language too.\n ----------------------------------------------------------------------- */\n // Both spellings are the same hub: .com redirects to the bare .amazon gTLD.\n // Matching only one is precisely the bug the old code had.\n var INTERNAL_HOSTS = [\"developer-docs.amazon\", \"developer-docs.amazon.com\"];\n\n function currentLangSeg() {\n var parts = location.pathname.split(\"/\").filter(Boolean);\n for (var i = 0; i \u003c parts.length; i++) {\n if (LANG_SEG.test(parts[i])) return parts[i].slice(5); // \"es_ES\"\n }\n return null;\n }\n\n // First segment that is neither a language nor a section — i.e. the child\n // project slug. sp-api and amazon-shipping are separate projects and must\n // not have each other's language prefix pushed onto them.\n function projectOf(pathname) {\n var parts = pathname.split(\"/\").filter(Boolean)\n .filter(function (p) { return !LANG_SEG.test(p); });\n if (!parts.length) return null;\n if (SECTIONS.index