n btn.addEventListener(\n 'click',\n evt => {\n evt.preventDefault();\n evt.stopPropagation();\n\n const expanded = btn.getAttribute('aria-expanded') === 'true';\n const next = !expanded;\n\n btn.setAttribute('aria-expanded', String(next));\n\n // Toggle class on \u003cli> for existing styles\n if (next) {\n li.classList.add('subnav-expanded');\n } else {\n li.classList.remove('subnav-expanded');\n }\n\n // Show/hide the subpages UL\n if (subpages) {\n if (next) {\n subpages.style.display = '';\n } else {\n subpages.style.display = 'none';\n }\n }\n\n // --- 3) Rotate the chevron icon ourselves ---\n const icon = btn.querySelector(ICON_SELECTOR);\n if (icon) {\n if (next) {\n icon.classList.add('rm-sidebar-rotated');\n } else {\n icon.classList.remove('rm-sidebar-rotated');\n }\n }\n },\n { passive: false }\n );\n });\n }\n\n function initSidebarA11yFix() {\n enhanceSidebar();\n\n const sidebarRoot =\n document.querySelector('.rm-Sidebar') ||\n document.querySelector('[class*=\"Sidebar\"][role=\"navigation\"]');\n\n if (!sidebarRoot || sidebarRoot.__sidebarA11yObserver) return;\n\n const observer = new MutationObserver(mutations => {\n let changed = false;\n for (const m of mutations) {\n if (m.addedNodes && m.addedNodes.length) {\n changed = true;\n break;\n }\n }\n if (changed) enhanceSidebar(sidebarRoot);\n });\n\n observer.observe(sidebarRoot, { childList: true, subtree: true });\n sidebarRoot.__sidebarA11yObserver = observer;\n }\n\n if (document.readyState === 'loading') {\n document.addEventListener('DOMContentLoaded', initSidebarA11yFix);\n } else {\n initSidebarA11yFix();\n }\n\n if (window.jQuery) {\n jQuery(window).on('pageLoad.sidebarA11yFix', initSidebarA11yFix);\n } else {\n window.addEventListener('pageLoad', initSidebarA11yFix);\n }\n})();\n\n\n /** Custom Recipe Design/Functionality per ReadMe */\n\n(() => {\n // ---- Categories + aliases -----------------------------------------------\n const CATEGORIES = [\n 'Application Management', \n 'Data Kiosk', \n 'Fulfillment Inbound',\n 'Listings Items',\n 'Merchant Fulfillment', \n 'Performance Management',\n 'Product Pricing',\n 'Vendor Direct Fulfillment'\n ];\n const ALIASES = {\n AM: 'Application Management',\n DK: 'Data Kiosk',\n FI: 'Fulfillment Inbound',\n LI: 'Listings Items',\n MCF: 'Merchant Fulfillment',\n PM: 'Performance Management',\n PP: 'Product Pricing',\n VDF: 'Vendor Direct Fulfillment'\n };\n const TOKEN_RE = /\\$\\{([^}]+)\\}\\$/g;\n const normalizeTag = (raw) => {\n const s = raw.trim();\n if (CATEGORIES.includes(s)) return s;\n const upper = s.toUpperCase();\n return ALIASES[upper] || null;\n };\n\n // ---- Token scrubber -----------------------------------------------------\n function cleanTokens(scope, {assignTags = false} = {}) {\n const walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT);\n const found = new Set();\n const toClean = [];\n let n;\n while ((n = walker.nextNode())) {\n const txt = n.nodeValue;\n if (!txt || txt.indexOf('${') === -1) continue;\n let hit = false;\n txt.replace(TOKEN_RE, (_, group) => {\n console.log(\"🔎 Matched token group:\", JSON.stringify(group));\n group.split(',').forEach(t => {\n const trimmed = t.trim();\n const tag = normalizeTag(trimmed);\n console.log(\" → raw:\", JSON.stringify(t),\n \"trimmed:\", JSON.stringify(trimmed),\n \"normalized:\", tag);\n if (tag) found.add(tag);\n });\n hit = true;\n return '';\n });\n if (hit) toClean.push(n);\n }\n toClean.forEach(n => {\n n.nodeValue = n.nodeValue.replace(TOKEN_RE, '').replace(/\\s{2,}/g, ' ').trim();\n });\n if (assignTags && found.size) {\n scope.dataset.tags = Array.from(found).join(',');\n }\n }\n\n // ---- Grid initializer ---------------------------------------------------\n function initGrid() {\n const grid = document.querySelector('.TutorialGrid26plsmAq5mws');\n if (!grid) return;\n\n // prevent duplicate hero\n if (grid.parentElement.querySelector(':scope > .rf-Hero')) return;\n\n const cards = Array.from(\n grid.querySelectorAll('li.TutorialCard2XH0Nnhtx8xA.rm-RecipeCard,[data-testid=\"recipe-card\"].rm-RecipeCard')\n );\n cards.forEach(li => cleanTokens(li, {assignTags: true}));\n\n // Inject hero + pills\n const wrap = grid.parentElement;\n const hero = document.createElement('section');\n hero.className = 'rf-Hero';\n hero.innerHTML = `\n \u003cdiv class=\"rf-Head\">\n \u003ch1>Selling Partner API Code Samples\u003c/h1>\n \u003cp>Walkthroughs that highlight API capabilities, best practices, and optimal use cases\u003c/p>\n \u003c/div>\n \u003cnav class=\"rf-Pills\" role=\"tablist\" aria-label=\"Recipe filters\">\u003c/nav>\n `;\n wrap.insertBefore(hero, grid);\n\n const pillBar = hero.querySelector('.rf-Pills');\n const pillNames = ['All', ...CATEGORIES];\n\n pillNames.forEach((name, i) => {\n const btn = document.createElement('button');\n btn.type = 'button';\n btn.className = 'rf-Pill' + (i === 0 ? ' is-active' : '');\n btn.textContent = name;\n btn.setAttribute('aria-pressed', i === 0 ? 'true' : 'false');\n\n btn.addEventListener('click', () => {\n pillBar.querySelectorAll('.rf-Pill').forEach(b => {\n b.classList.remove('is-active');\n b.setAttribute('aria-pressed', 'false');\n });\n btn.classList.add('is-active');\n btn.setAttribute('aria-pressed', 'true');\n\n const selected = name === 'All' ? null : name;\n cards.forEach(li => {\n const tags = (li.dataset.tags || '')\n .split(',')\n .map(s => s.trim())\n .filter(Boolean);\n const show = !selected || tags.includes(selected);\n li.classList.toggle('rf-hidden', !show);\n });\n });\n\n pillBar.appendChild(btn);\n });\n\n // Deep-link: ?filter=MCF\n const param = new URLSearchParams(location.search).get('filter');\n if (param && pillNames.includes(param)) {\n const match = Array.from(pillBar.children).find(b => b.textContent === param);\n if (match) match.click();\n }\n }\n\n // ---- Modal scrubber -----------------------------------------------------\n function setupModalWatcher(root) {\n const modalObs = new MutationObserver(() => {\n const modal = root.querySelector('.rm-Recipes-modal');\n if (modal) {\n modal.querySelectorAll('.rm-Markdown').forEach(md => {\n cleanTokens(md, {assignTags: false});\n });\n }\n });\n modalObs.observe(root, { childList: true, subtree: true });\n }\n\n // ---- Wait-for utility ---------------------------------------------------\n function waitFor(selector, cb) {\n const el = document.querySelector(selector);\n if (el) return cb(el);\n const obs = new MutationObserver(() => {\n const found = document.querySelector(selector);\n if (found) {\n obs.disconnect();\n cb(found);\n }\n });\n obs.observe(document.body, { childList: true, subtree: true });\n }\n\n // ---- SPA route hook -----------------------------------------------------\n function hookHistory(fn) {\n const _push = history.pushState;\n history.pushState = function(){ _push.apply(this, arguments); fn(); };\n const _replace = history.replaceState;\n history.replaceState = function(){ _replace.apply(this, arguments); fn(); };\n window.addEventListener('popstate', fn);\n }\n\n // ---- Init ---------------------------------------------------------------\n // The hero is injected into a React-owned parent (wrap.insertBefore below\n // the grid), so a later React commit can discard it. waitFor() disconnects\n // its observer after the first match, so nothing ever put the hero back —\n // which is why it vanished on SPA navigation into recipes and only a hard\n // reload brought it back. Keep watching for the life of the page and\n // re-inject whenever it has gone missing, after the DOM has settled so we\n // never inject mid-commit. initGrid() already no-ops when a .rf-Hero is\n // present, so re-running it is free.\n const GRID_SETTLE_MS = 300;\n let gridTimer;\n function ensureGrid() {\n clearTimeout(gridTimer);\n gridTimer = setTimeout(() => {\n if (document.querySelector('.TutorialGrid26plsmAq5mws')) initGrid();\n }, GRID_SETTLE_MS);\n }\n new MutationObserver(ensureGrid).observe(document.body, { childList: true, subtree: true });\n hookHistory(ensureGrid); // also wires popstate\n ensureGrid();\n waitFor('#modal-root', setupModalWatcher);\n})();\n\n\n\n// ─── Full-page navigation for top-level section links ────────────────────────\n// The Refactored header routes Home / Documentation / Code Samples / API\n// Reference / Announcements through the SPA router. Crossing between sections\n// — notably recipes -> reference — leaves this file's reference-sidebar\n// customization half-initialised, because each section mounts a different tree\n// and our hooks assume a clean boot. Rather than chase every ordering case,\n// force a real document navigation for those links so every script starts from\n// scratch. This replaces an older sessionStorage-gated `handleReload()` that\n// called location.reload() AFTER the SPA had already routed: that fired at most\n// once per session (hence the intermittent behaviour) and cost two page loads.\n;(function () {\n // Matching on the header class alone was not enough: a cross-section link\n // inside recipe content or a sidebar routed through the SPA anyway, which is\n // how `recipes/welcome-to-api-references` ended up being fetched — the router\n // kept the recipes section while swapping in a reference slug. So key off the\n // section in the URL, not off which element was clicked.\n const SECTIONS = ['docs', 'recipes', 'reference', 'changelog', 'discuss', 'page'];\n function sectionOf(pathname) {\n return pathname.split('/').filter(Boolean).find(s => SECTIONS.includes(s)) || 'root';\n }\n\n document.addEventListener('click', event => {\n if (event.defaultPrevented) return;\n // Leave modifier and middle clicks alone so \"open in new tab\" still works.\n if (event.button !== 0 || event.metaKey || event.ctrlKey ||\n event.shiftKey || event.altKey) return;\n\n const link = event.target.closest('a[href]');\n if (!link) return;\n // Respect explicit new-tab / download intent.\n if (link.target && link.target !== '_self') return;\n if (link.hasAttribute('download')) return;\n\n let url;\n try {\n url = new URL(link.getAttribute('href'), location.href);\n } catch (e) {\n return;\n }\n // Cross-origin items (GitHub, Videos, and the absolute\n // developer-docs.amazon.com links when viewed from a preview domain) keep\n // their normal behaviour.\n if (url.origin !== location.origin) return;\n\n // Same-section navigation stays SPA — that is the common case and it works.\n // Only crossing sections gets a full load.\n if (sectionOf(url.pathname) === sectionOf(location.pathname)) return;\n\n event.preventDefault();\n event.stopPropagation();\n console.debug('[sp-api] cross-section click -> full load',\n sectionOf(location.pathname), '->', sectionOf(url.pathname), url.pathname);\n // Same window, same frame. Deliberately NOT window.top.location, which\n // would blow out of the dash's preview iframe.\n window.location.assign(url.href);\n }, true); // capture, so we beat the SPA router's own handler\n})();\n\n// ─── Sidebar ─────────────────────────────────────────────────────────────────\n;(function () {\n // ─── Sidebar rearrange ─────────────────────────────────────────────────────\n function regroupSidebar() {\n const root = document.getElementById('reference-sidebar');\n if (!root) return;\n const sidebar = root.querySelector('.rm-Sidebar');\n if (!sidebar) return;\n\n // inject CSS once\n if (!document.getElementById('custom-sidebar-style')) {\n const s = document.createElement('style');\n s.id = 'custom-sidebar-style';\n s.textContent = `\n #reference-sidebar ul.rm-Sidebar-list,\n #reference-sidebar ul.rm-Sidebar-sublist { list-style:none; padding:0; margin:11px 0; }\n #reference-sidebar h2.rm-Sidebar-heading { font-size:15px; padding:5px; margin:0; border-bottom:1px solid #ececec; cursor:pointer; }\n #reference-sidebar { overscroll-behavior:contain; }\n `;\n document.head.appendChild(s);\n }\n\n const stripVer = t => t.replace(/\\sv\\d.*$/, '').trim();\n\n // Refactored renders a leading headingless \u003csection> (it holds the\n // Sidebar-link_hidden items: Getting Started / Authentication / My\n // Requests). Reading .innerText off its missing \u003ch2> threw, which aborted\n // this function before it could add .regenerated — and ProjectCSS holds\n // .rm-Sidebar at opacity 0 with a spinner until that class lands. Legacy\n // never rendered that section, which is why only Refactored hung.\n // Read headings defensively and leave headingless sections where they are.\n const headingText = s => s.querySelector('h2')?.innerText.trim() || '';\n const secs = Array.from(sidebar.querySelectorAll('section.rm-Sidebar-section'))\n .filter(s => headingText(s));\n const getStarted = secs.find(s => /^(Get|Getting)\\s*Started/i.test(headingText(s)));\n const landing = secs.find(s => /Landing Pages/i.test(headingText(s)));\n\n // build landing lookup\n const landingMap = {};\n if (landing) {\n landing.querySelectorAll('a.rm-Sidebar-link').forEach(a => {\n landingMap[stripVer(a.innerText)] = a.cloneNode(true);\n });\n }\n\n // group by API base \n const apiSecs = secs.filter(s => s !== getStarted && s !== landing);\n\n // References custom bundles config\n const GROUPS = [\n // FBA & Vendor Retail Procurement—with regex to catch any future versioned pages,\n // plus their static sub-APIs\n { title: 'Fulfillment by Amazon (FBA)', pattern: /^Fulfillment by Amazon \\(FBA\\)/, keys: ['FBA Inbound Eligibility','FBA Inventory'] },\n { title: 'Vendor Retail Procurement', pattern: /^Vendor Retail Procurement/, keys: ['Vendor Invoices','Vendor Shipments','Vendor Transaction Status','Vendor Orders'] },\n // Invoices v2024 goes under Invoicing\n { title: 'Invoicing', keys: ['Shipment Invoicing', 'Invoices v2024-06-19 (Brazil Only)'] },\n // Every other bundle catches any \"X v…\" variants automatically,\n // plus the one-off pages you care about:\n { title: 'Finances', pattern: /^Finances/, keys: ['Transfers', 'Invoices v2026-06-25'] },\n { title: 'Listings', pattern: /^Listings/, k