es = [\"button\", \"link\", \"checkbox\", \"switch\", \"tab\", \"menuitem\"];\n roles.forEach((role) => {\n document.querySelectorAll(`[role=\"${role}\"]`).forEach((el) => {\n const tag = el.tagName;\n if ([\"A\", \"BUTTON\", \"INPUT\", \"TEXTAREA\", \"SELECT\"].includes(tag))\n return;\n \n // Skip anything inside the search container\n if (el.closest(\"#hub-search\")) return;\n \n if (!el.hasAttribute(\"tabindex\")) el.setAttribute(\"tabindex\", \"0\");\n processed++;\n \n if (role === \"button\" && !el.dataset._hasKeyHandler) {\n el.addEventListener(\"keydown\", (e) => {\n // Only simulate click on ENTER; leave SPACE alone unless you're sure\n if (e.key === \"Enter\") {\n e.preventDefault();\n el.click?.();\n }\n });\n el.dataset._hasKeyHandler = \"true\";\n }\n });\n });\n }\n \n /*** #9 - \u003ctable> elements have no accessible name ***/\n function labelTables() {\n let processed = 0;\n document.querySelectorAll(\"table\").forEach((table, i) => {\n if (\n table.hasAttribute(\"aria-label\") ||\n table.hasAttribute(\"aria-labelledby\") ||\n table.hasAttribute(\"title\")\n )\n return;\n const caption = table.querySelector(\"caption\");\n if (caption?.textContent.trim()) {\n table.setAttribute(\"aria-label\", caption.textContent.trim());\n processed++;\n return;\n }\n let prev = table.previousElementSibling;\n while (prev && !/^H[1-6]$/.test(prev.tagName)) {\n prev = prev.previousElementSibling;\n }\n if (prev?.textContent.trim()) {\n table.setAttribute(\"aria-label\", prev.textContent.trim());\n processed++;\n return;\n }\n table.setAttribute(\"aria-label\", `Data table ${i + 1}`);\n processed++;\n });\n }\n \n /*** #10 - \u003cblockquote> used for layout, not quotes ***/\n function fixBlockquotes() {\n let processed = 0;\n document.querySelectorAll(\"blockquote.callout\").forEach((bq) => {\n if (bq.hasAttribute(\"cite\")) return;\n const newEl = document.createElement(\"div\");\n newEl.className = bq.className;\n if (bq.hasAttribute(\"theme\"))\n newEl.setAttribute(\"theme\", bq.getAttribute(\"theme\"));\n newEl.innerHTML = bq.innerHTML;\n bq.replaceWith(newEl);\n processed++;\n });\n }\n \n /*** #11 - Inline quotes not wrapped in semantic \u003cq> ***/\n function fixInlineQuotes() {\n let processed = 0;\n document.querySelectorAll(\"p\").forEach((p) => {\n const text = p.textContent.trim();\n if (/^[\"“].+[\"”]$/.test(text) && !p.querySelector(\"q\")) {\n const quote = text.replace(/^[\"“]|[\"”]$/g, \"\");\n p.innerHTML = `\u003cq>${quote}\u003c/q>`;\n processed++;\n }\n });\n }\n \n /*** #12 - Label names for icons (expand/collapse) ***/\n function fixIconLabels() {\n let processed = 0;\n // Find all icon elements that are used for expand/collapse, assumed to have a specific class\n document\n .querySelectorAll(\"i.Sidebar-link-expandIcon2yVH6SarI6NW\")\n .forEach((icon) => {\n if (!icon.hasAttribute(\"aria-label\")) {\n // Check the parent button's aria-expanded attribute to infer state\n const parentBtn = icon.closest(\"button\");\n let label = \"Expand\";\n if (parentBtn) {\n const expanded = parentBtn.getAttribute(\"aria-expanded\");\n label = expanded === \"true\" ? \"Collapse\" : \"Expand\";\n }\n icon.setAttribute(\"role\", \"img\");\n icon.setAttribute(\"aria-label\", label);\n processed++;\n }\n });\n }\n \n /*** #13 - Warn users before opening a new window ***/\n function fixExternalLinks() {\n let processed = 0;\n document.querySelectorAll('a[target=\"_blank\"]').forEach((link) => {\n let text = link.innerText.trim() || link.textContent.trim();\n if (text && !text.toLowerCase().includes(\"opens in a new window\")) {\n const newLabel = `${text} (opens in a new window)`;\n link.setAttribute(\"aria-label\", newLabel);\n processed++;\n }\n });\n }\n \n /*** Master apply function ***/\n function applyAllFixes() {\n fixLandmarkLabels(); // #1: Unique labeling in top nav bar, footer, side mini TOC\n fixHeadings(); // #5: Headings need heading element or role\n enhanceCodeTabs(); // #7: Code block tabs are not keyboard navigable\n fixWidgetRoles(); // #8: Widget roles are not actually tabbable\n labelTables(); // #9: \u003ctable> elements have no accessible name\n\n fixInlineQuotes(); // #11: Inline quotes not wrapped in semantic \u003cq>\n fixIconLabels(); // #12: Label names for icons (expand/collapse)\n fixExternalLinks(); // #13: Warn users before opening a new window\n }\n \n applyAllFixes();\n \n let debounceTimer;\n const observer = new MutationObserver((mutations) => {\n clearTimeout(debounceTimer);\n debounceTimer = setTimeout(() => {\n try {\n applyAllFixes();\n } catch (error) {\n }\n }, 300);\n });\n \n observer.observe(document.body, {\n childList: true,\n subtree: true,\n });\n })();","html_promo":"","html_body":"","html_footer":"\u003cstyle>\n .footer-container {\n display: flex;\n align-items: center;\n justify-content: space-between;\n gap: 24px;\n width: 100%;\n margin-top: 32px;\n padding: 24px 40px;\n box-sizing: border-box;\n border-top: 1px solid #dfe5e7;\n background: #f7f9f9;\n color: #5f6d73;\n font-size: 14px;\n line-height: 1.5;\n }\n\n .footer-left-container,\n .footer-sub-container {\n display: flex;\n align-items: center;\n }\n\n .footer-container a {\n color: #526f79;\n font-weight: 500;\n text-decoration: none;\n transition: color 0.15s ease;\n }\n\n .footer-container a:hover {\n color: #263f49;\n text-decoration: underline;\n }\n\n /* Dark Mode */\n [data-color-mode=\"dark\"] .footer-container {\n background: #131b28;\n border-top-color: #344052;\n color: #aeb8c4;\n }\n\n [data-color-mode=\"dark\"] .footer-container a {\n color: #b6d0d3;\n }\n\n [data-color-mode=\"dark\"] .footer-container a:hover {\n color: #ffffff;\n }\n\n /* Mobile */\n @media (max-width: 768px) {\n .footer-container {\n flex-direction: column;\n align-items: flex-start;\n gap: 12px;\n padding: 22px 20px;\n }\n\n .footer-sub-container {\n flex-wrap: wrap;\n }\n }\n\u003c/style>\n\n\u003cdiv class=\"footer-container\">\n \u003cspan class=\"footer-left-container\">\n \u003ca hre