olor-mode') {\n updateLogo();\n }\n }\n });\n observer.observe(document.documentElement, { attributes: true });\n})();\n\u003c/script>","html_footer_meta":"\u003c!-- Keep the language selector commented -->\n\u003c!--\n\u003cselect id=\"global-lang\" class=\"language-selector\" onchange=\"redirectToSelectedLanguage(this)\">\n \u003coption value=\"amazon-group.readme.io\">English\u003c/option>\n \u003coption value=\"amazon-portuguese-group.readme.io\">Portuguese\u003c/option>\n \u003coption value=\"amazon-japanese-group.readme.io\">Japanese\u003c/option>\n\u003c/select>\n\n\u003cstyle>\n .language-selector {\n width: 150px;\n outline: none;\n border-color: #999;\n color: #999;\n padding: 5px;\n }\n #global-lang {\n float: right;\n margin-top: 5px;\n }\n\u003c/style>\n\n\u003cscript>\n\tfunction initGlobalLanguageSelectorPosition() {\n\tconst userSelector = $('#header-nav-right');\n const langSelector = $('#global-lang');\n if (userSelector.length && langSelector.length) {\n langSelector.insertAfter(userSelector);\n }\n }\n function initCopyRightYear() {\n document.getElementById('copyrightSection').appendChild(document.createTextNode(\"© 1996-\" + new Date().getFullYear()+ \", Amazon.com, Inc.\"));\n }\n initGlobalLanguageSelectorPosition();\n initCopyRightYear();\n\u003c/script>\n-->","global_landing_page":{"html":"\u003cstyle>\n /* =========================================================\n AMAZON SP-API GLP\n ========================================================= */\n\n\n /* =========================================================\n HIDE SITEWIDE FOOTER ON THIS GLP\n ========================================================= */\n\n .footer-container {\n display: none !important;\n }\n\n\n /* =========================================================\n README HEADER\n ========================================================= */\n\n .Header-topuTMpygDG4e1V {\n background: #b6d0d3;\n }\n\n .Header-logo-img3YvV4lcGKkeb {\n width: 225px;\n height: auto;\n margin-top: