/* ============================================================================ TRANSIFEX LIVE — stock widget ---------------------------------------------------------------------------- Transifex renders and positions its own picker. We insert no DOM and touch no ReadMe component. This replaces the old code that relocated ReadMe's native language dropdown into the header, which cannot work now that that dropdown no longer exists. Why the defineProperty rather than a plain `window.liveSettings = {...}`: ReadMe injects its own liveSettings block with `picker: false` in a <script> that comes AFTER all custom JS in the document (~line 2580 of the rendered page). A plain assignment here is silently overwritten and the widget never appears. The accessor below merges whatever ReadMe assigns and removes `picker` so the default widget renders. Lives at GROUP level so it also covers the GLP, where ReadMe injects nothing at all. ========================================================================== */ ;(function () { var API_KEY = "9251cba762e8402cae3a821b20521b05"; // `picker` is a CSS selector string (where to mount) or false (disable). // There is no `true`. The default floating picker renders when the key is // ABSENT, so we delete it rather than set it — ReadMe's injected block sets // `picker: false`, which is what was suppressing the widget. var settings = { api_key: API_KEY, dynamic: true }; try { Object.defineProperty(window, "liveSettings", { configurable: true, enumerable: true, get: function () { return settings; }, set: function (incoming) { settings = incoming || {}; if (!settings.api_key) settings.api_key = API_KEY; delete settings.picker; // let Transifex render its own default picker settings.dynamic = true; // required: the hub is a React SPA } }); } catch (e) { // Property already locked by something else — fall back to assignment. window.liveSettings = settings; } // Load live.js only if nothing else already has. ReadMe's injected block // loads it today; this fallback keeps the widget working if that record is // later turned off. Guarding on both the global and the tag avoids the // double-load that produced the duplicate pickers in the Transifex ticket. function ensureLive() { if (window.Transifex && window.Transifex.live) return; if (document.querySelector('script[src*="cdn.transifex.com/live.js"]')) return; var s = document.createElement("script"); s.type = "text/javascript"; s.async = true; s.src = "//cdn.transifex.com/live.js"; document.head.appendChild(s); } if (document.readyState === "loading") { window.addEventListener("DOMContentLoaded", function () { setTimeout(ensureLive, 0); }); } else { setTimeout(ensureLive, 0); } /* -------------------------------------------------------------------------- Relocate Transifex's picker into the header, left of "Developer Hub". Amazon asked for top-right rather than Transifex's default bottom-left. We move Transifex's OWN node (#tx-live-lang-container) into ReadMe's header. Note the direction: the old code did the reverse — it pulled ReadMe's native dropdown OUT of React's tree, which is what caused the "removeChild" crashes. Appending a foreign node INTO a React container is the safe direction; the only risk is React dropping it on re-render, which the observer below repairs. ----------------------------------------------------------------------- */ var PICKER_ID = "tx-live-lang-container"; var HEADER_SEL = ".rm-Header-right"; // stable rm-* contract var ANCHOR_SEL = '[class*="Header-right_desktop"]'; // hashed -> wildcard function placePicker() { var picker = document.getElementById(PICKER_ID); var header = document.querySelector(HEADER_SEL); if (!picker || !header) return false; // Sit INSIDE the Developer Hub / API Status / Support group, as its first // child. That group is its own flex row with gap:var(--xs), so being a // member of it lines the picker up with those links exactly. Inserting as // a sibling of the group instead left a large gap, because the pi